insert into public.partners (slug, name, website_url, location, craft, craft_de, bio, bio_de, portrait_url, workshop_images) values ('vaidava-ceramics', 'VAIDAVA CERAMICS', NULL, 'Vaidava, Latvia', 'Handcrafted Latvian ceramics', 'Handgefertigte lettische Keramik', 'Vaidava Ceramics creates artisanal terracotta-inspired tableware with Nordic minimalism and Baltic heritage.', 'Vaidava Ceramics kreiert handwerklich von Terrakotta inspiriertes Geschirr mit nordischem Minimalismus und baltischem Erbe.', '/partners/vaidava-ceramics/images/4774e6d78e7af1.jpg', '["/partners/vaidava-ceramics/images/4774e6d78e7af1.jpg", "/partners/vaidava-ceramics/images/af5f4c30981d1d.jpg", "/partners/vaidava-ceramics/images/ccd37b81926496.jpg"]'::jsonb);
insert into public.partners (slug, name, website_url, location, craft, craft_de, bio, bio_de, portrait_url, workshop_images) values ('cepli', 'Cepļi', NULL, 'Vidzemes jūrmalas piekraste, Latvia', 'Black ceramics and tableware', 'Schwarze Keramik und Geschirr', 'Cepļi is a Latvian black-ceramics workshop active since 1985, producing tableware and traditional clay objects.', 'Cepļi ist eine lettische Werkstatt für schwarze Keramik, die seit 1985 tätig ist und Geschirr und traditionelle Tongegenstände herstellt.', '/partners/cepli/images/7c6884bc6a6742.jpg', '["/partners/cepli/images/7c6884bc6a6742.jpg", "/partners/cepli/images/94c32585c7bbd4.jpg", "/partners/cepli/images/544745097361ab.jpg"]'::jsonb);
insert into public.partners (slug, name, website_url, location, craft, craft_de, bio, bio_de, portrait_url, workshop_images) values ('cerannic', 'cerannic', NULL, 'Latvia', 'Handmade ceramics', 'Handgefertigte Keramik', 'cerannic creates handcrafted ceramics and giftable objects in limited runs.', 'Cerannic stellt handgefertigte Keramik und Geschenkartikel in limitierten Auflagen her.', '/partners/cerannic/images/93b0b19bd9d005.jpg', '["/partners/cerannic/images/93b0b19bd9d005.jpg", "/partners/cerannic/images/c4badaee2e25c1.png", "/partners/cerannic/images/739141683668e9.jpeg"]'::jsonb);
insert into public.partners (slug, name, website_url, location, craft, craft_de, bio, bio_de, portrait_url, workshop_images) values ('latvijas-labumu-tirgus-mals', 'Latvijas Labumu Tirgus: Māls', NULL, 'Latvia', 'Clay and ceramics marketplace', 'Marktplatz für Ton und Keramik', 'The clay section of Latvijas Labumu Tirgus features many independent ceramic makers from across Latvia.', 'In der Tonabteilung von Latvijas Labumu Tirgus sind viele unabhängige Keramikhersteller aus ganz Lettland vertreten.', '/partners/latvijas-labumu-tirgus-mals/images/02b43969680a4b.jpg', '["/partners/latvijas-labumu-tirgus-mals/images/02b43969680a4b.jpg", "/partners/latvijas-labumu-tirgus-mals/images/11b844a6531e3c.jpg", "/partners/latvijas-labumu-tirgus-mals/images/545288670e8f12.jpg"]'::jsonb);
