insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'A bowl of soup/peas', 'A bowl of soup/peas. The bowl is made by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowl is decorated in engraving technique. Can be used in contact with food products, including wet products, in the microwave and oven. Hand washing is recommended for long term use.', 'A bowl of soup/peas. The bowl is made by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowl is decorated in engraving technique. Can be used in contact with food products, including wet products, in the microwave and oven. Hand washing is recommended for long term use.', 'Bļodas, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-zupas-zirnu-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Eine Schüssel Suppe/Erbsen', 'Eine Schüssel Suppe/Erbsen. Die Schale wird von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schale ist in Gravurtechnik verziert. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen.', 'Eine Schüssel Suppe/Erbsen. Die Schale wird von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schale ist in Gravurtechnik verziert. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen.', 'Bļodas, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-zupas-zirnu-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'A loose salad bowl.', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C.', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C.', 'Bļodas, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-lezena-salatu-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Eine lose Salatschüssel.', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C.', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C.', 'Bļodas, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-lezena-salatu-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'A vase', 'A vase. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1260°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'A vase. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1260°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'Trauki no akmens masas, vāzes', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-vaze-19';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Ein Geschirr', 'Eine Vase. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1260°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Eine Vase. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1260°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Trauki no akmens masas, vāzes', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-vaze-19';
