insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Alus kauss 0,5L', 'Beer cup 0.5L. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Beer cup 0.5L. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Krūzes, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-alus-kauss-12l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Alukauss 0,5L', 'Bierbecher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bierbecher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Krūzes, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-alus-kauss-12l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Aroma lamp', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'Aromalampas, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-aromalampa-8';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Aromalampe', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Aromalampas, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-aromalampa-8';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Aroma lamp', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'Aromalampas, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-aromalampa-7';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Aromalampe', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Aromalampas, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-aromalampa-7';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Aroma lamp', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'The aroma lamp is made by hand on a potter''s wheel from dark stone mass. Firing temperature – 1050°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'Aromalampas, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-aromalampa-6';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Aromalampe', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus dunkler Steinmasse gefertigt. Brenntemperatur – 1050°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Aromalampas, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-aromalampa-6';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Aroma lamp', 'The aroma lamp is made by hand on a potter''s wheel made of white stone mass. Firing temperature – 1250°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'The aroma lamp is made by hand on a potter''s wheel made of white stone mass. Firing temperature – 1250°C. The aroma lamp consists of two parts - the main part, where a candle can be easily placed in the opening, and the upper oil-heated bowl, which can be easily removed to refill or wash. The oil-heated bowl is glazed inside, which ensures easy dishwashing. The glaze used is friendly to the environment and human health without harmful impurities.', 'Aromalampas, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-aromalampa-5';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Aromalampe', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Brenntemperatur – 1250°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Aromalampe wird von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Brenntemperatur – 1250°C. Die Aromalampe besteht aus zwei Teilen – dem Hauptteil, in dessen Öffnung problemlos eine Kerze platziert werden kann, und der oberen ölbeheizten Schale, die zum Nachfüllen oder Waschen einfach abgenommen werden kann. Die ölbeheizte Schüssel ist innen glasiert, was ein einfaches Geschirrspülen gewährleistet. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Aromalampas, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-aromalampa-5';
