insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 0.4L', 'Bowl 0.4L. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bowl 0.4L. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-bloda-04l-2';
