insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Schüssel 0,7L', 'Schüssel 0,7L. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Schüssel 0,7L. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-bloda-07l-3';
