insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Schüssel 0,7L', 'Schüssel 0,7L. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Schüssel 0,7L. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Bļodas, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-bloda-07l-2';
