insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Schüssel 0,7L', 'Die Schale wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Schale wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-bloda-07l';
