insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl with ash 1.5 L', 'A bowl of ash. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1260°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'A bowl of ash. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1260°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'Bļodas, Dabas raksti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-bloda-ar-osu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Schüssel mit Asche 1,5 L', 'Eine Schüssel mit Asche. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1260°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Eine Schüssel mit Asche. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1260°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Bļodas, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-bloda-ar-osu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Breakfast bowl.', 'Breakfast bowl 0.35L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C.', 'Breakfast bowl 0.35L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C.', 'Bļodas, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-brokastu-bloda';
