insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Breakfast/dessert bowl 0.4L', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in engraving technique. The inside is glazed with a bright dark blue smoky glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in engraving technique. The inside is glazed with a bright dark blue smoky glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, Dabas raksti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Frühstücks-/Dessertschüssel 0,4L', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Von Hand in Gravurtechnik verziert. Die Innenseite ist mit einer leuchtend dunkelblauen Rauchglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Von Hand in Gravurtechnik verziert. Die Innenseite ist mit einer leuchtend dunkelblauen Rauchglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Breakfast/dessert bowl 0.4L', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in engraving technique. The inside is glazed with a bright green effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in engraving technique. The inside is glazed with a bright green effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, Dabas raksti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Frühstücks-/Dessertschüssel 0,4L', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Von Hand in Gravurtechnik verziert. Die Innenseite ist mit einer hellgrünen Effektglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Von Hand in Gravurtechnik verziert. Die Innenseite ist mit einer hellgrünen Effektglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Breakfast/dessert bowl 0.4L', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in the engraving technique, using motifs of natural patterns. The inside is glazed with a bright red effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bowl 0.4L. Firing temperature 1250 °C. Decorated by hand in the engraving technique, using motifs of natural patterns. The inside is glazed with a bright red effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, Dabas raksti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Frühstücks-/Dessertschüssel 0,4L', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Handverziert in Gravurtechnik mit Motiven natürlicher Muster. Die Innenseite ist mit einer leuchtend roten Effektglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Schüssel 0,4L. Brenntemperatur 1250 °C. Handverziert in Gravurtechnik mit Motiven natürlicher Muster. Die Innenseite ist mit einer leuchtend roten Effektglasur glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-brokastu-deserta-bloda-04l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Butter dish', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. Can be used in contact with food products, including wet products, in the microwave and oven. Hand wash is recommended for long-term use.', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. Can be used in contact with food products, including wet products, in the microwave and oven. Hand wash is recommended for long-term use.', 'Melnā/svēpētā keramika, Sviesta trauki', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-sviesta-trauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Butterdose', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Für den Langzeitgebrauch wird Handwäsche empfohlen.', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Für den Langzeitgebrauch wird Handwäsche empfohlen.', 'Melnā/svēpētā keramika, Sviesta trauki', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-sviesta-trauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Cake plate 18 cm', 'The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-kuku-skivis-18-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Kuchenteller 18 cm', 'Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-kuku-skivis-18-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Candlestick', 'Candlestick. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Candlestick. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Melnā/svēpētā keramika, svečturi', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-svecturis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Leuchter', 'Leuchter. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Leuchter. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Melnā/svēpētā keramika, svečturi', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-svecturis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Coffee mug 0.25L', 'Coffee cup 0.25L. Crafted by hand on a potter''s wheel from gray stoneware. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with a black matte glaze, complemented by a bronze effect glaze. Especially suitable for preparing cappuccino with a coffee machine. The glaze used is friendly to the environment and human health without harmful impurities.', 'Coffee cup 0.25L. Crafted by hand on a potter''s wheel from gray stoneware. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with a black matte glaze, complemented by a bronze effect glaze. Especially suitable for preparing cappuccino with a coffee machine. The glaze used is friendly to the environment and human health without harmful impurities.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-kafijas-kruze-025l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Kaffeebecher 0,25L', 'Kaffeetasse 0,25 l. Handgefertigt auf einer Töpferscheibe aus grauem Steingut. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit einer schwarzen, matten Glasur, ergänzt durch eine Glasur mit Bronzeeffekt. Besonders geeignet für die Zubereitung von Cappuccino mit einer Kaffeemaschine. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Kaffeetasse 0,25 l. Handgefertigt auf einer Töpferscheibe aus grauem Steingut. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit einer schwarzen, matten Glasur, ergänzt durch eine Glasur mit Bronzeeffekt. Besonders geeignet für die Zubereitung von Cappuccino mit einer Kaffeemaschine. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-kafijas-kruze-025l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Cup of tea/broth/soup 0.5L', 'Mug 0.5L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Mug 0.5L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, Krūzes', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-buljona-zupas-kruze-0-5l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tasse Tee/Brühe/Suppe 0,5 l', 'Becher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Becher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, Krūzes', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-buljona-zupas-kruze-0-5l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dinnerware set &#8211; plate + bowl', 'Dish set. From the "LIGHT" collection. Firing temperature 1250 °C. Glazed with bright light effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Dish set. From the "LIGHT" collection. Firing temperature 1250 °C. Glazed with bright light effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'GAISMA, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-pusdienu-trauku-komplekts-skivis-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Teller + Schüssel', 'Geschirrset. Aus der „LIGHT“-Kollektion. Brenntemperatur 1250 °C. Glasiert mit heller Lichteffektglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Geschirrset. Aus der „LIGHT“-Kollektion. Brenntemperatur 1250 °C. Glasiert mit heller Lichteffektglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'GAISMA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-pusdienu-trauku-komplekts-skivis-bloda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; 2 tea/coffee glasses + plate', 'The glasses are shaped by hand on a potter''s wheel from gray stoneware and glazed with a black matte glaze. The plate is made by hand using plastic technique. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'The glasses are shaped by hand on a potter''s wheel from gray stoneware and glazed with a black matte glaze. The plate is made by hand using plastic technique. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'Komplekti, Melns un Zelts', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-glazes-2gbskivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; 2 Tee-/Kaffeegläser + Teller', 'Die Gläser werden von Hand auf einer Töpferscheibe aus grauem Steinzeug geformt und mit einer schwarzen, matten Glasur glasiert. Der Teller wird in plastischer Technik von Hand gefertigt. Verziert mit goldfarbenen Zeichnungen in Abziehbildtechnik. Brenntemperatur – 1250°C.', 'Die Gläser werden von Hand auf einer Töpferscheibe aus grauem Steinzeug geformt und mit einer schwarzen, matten Glasur glasiert. Der Teller wird in plastischer Technik von Hand gefertigt. Verziert mit goldfarbenen Zeichnungen in Abziehbildtechnik. Brenntemperatur – 1250°C.', 'Komplekti, Melns un Zelts', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-glazes-2gbskivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; 4 bowls + 4 plates', 'A set of dishes from the "Monochrome" collection, which emphasizes simplicity in shapes and glaze. Hand formed on a potter''s wheel from white stoneware and glazed with a black matte glaze. Firing temperature – 1250°C.', 'A set of dishes from the "Monochrome" collection, which emphasizes simplicity in shapes and glaze. Hand formed on a potter''s wheel from white stoneware and glazed with a black matte glaze. Firing temperature – 1250°C.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-4-blodas-4-skivji-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; 4 Schüsseln + 4 Teller', 'Ein Geschirrset aus der „Monochrome“-Kollektion, das Schlichtheit in Form und Glasur betont. Von Hand auf einer Töpferscheibe aus weißem Steingut geformt und mit einer schwarzen, matten Glasur glasiert. Brenntemperatur – 1250°C.', 'Ein Geschirrset aus der „Monochrome“-Kollektion, das Schlichtheit in Form und Glasur betont. Von Hand auf einer Töpferscheibe aus weißem Steingut geformt und mit einer schwarzen, matten Glasur glasiert. Brenntemperatur – 1250°C.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-4-blodas-4-skivji-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; Tea/coffee mug 0.5L+ plate 18 cm', 'The mug is made by hand on a potter''s wheel from gray stoneware. The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'The mug is made by hand on a potter''s wheel from gray stoneware. The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-kruze-05l-skivis-18-cm-2';
