insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Tee-/Kaffeebecher 0,5 l + Teller 18 cm', 'Der Becher wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Der Becher wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-kruze-05l-skivis-18-cm';
