insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; bowl 0.7L+ plate 22*24 cm', 'The bowl is made by hand on a potter''s wheel from gray stoneware. The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'The bowl is made by hand on a potter''s wheel from gray stoneware. The plate is made by hand using plastic technique. Firing temperature – 1250°C. From the "KARKLI GRAY BLOSSOMS" collection. Glazed with transparent matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-bloda-07l-skivis-2224-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Schüssel 0,7L+ Teller 22*24 cm', 'Die Schale wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Die Schale wird von Hand auf einer Töpferscheibe aus grauem Steinzeug gefertigt. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „KARKLI GREY BLOSSOMS“. Glasiert mit transparenter Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'KĀRKLI PELĒKIE ZIED, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-bloda-07l-skivis-2224-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; coffee cup 0.15 L + plate', 'A set of dishes from the "Monochrome" collection, which emphasizes simplicity in shapes and glaze. The oval plate is made by hand using the plastic technique, the cup is hand-turned from gray stone mass and glazed with black matte glaze, supplemented with bronze effect glaze. Perfect size for making one serving of coffee in a coffee machine.', 'A set of dishes from the "Monochrome" collection, which emphasizes simplicity in shapes and glaze. The oval plate is made by hand using the plastic technique, the cup is hand-turned from gray stone mass and glazed with black matte glaze, supplemented with bronze effect glaze. Perfect size for making one serving of coffee in a coffee machine.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-kafijas-kruze-015-l-skivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Kaffeetasse 0,15 L + Teller', 'Ein Geschirrset aus der „Monochrome“-Kollektion, das Schlichtheit in Form und Glasur betont. Der ovale Teller wird in plastischer Technik von Hand gefertigt, die Tasse ist aus grauer Steinmasse handgedreht und mit schwarzer Mattglasur glasiert, ergänzt durch Glasur mit Bronzeeffekt. Perfekte Größe für die Zubereitung einer Portion Kaffee in einer Kaffeemaschine.', 'Ein Geschirrset aus der „Monochrome“-Kollektion, das Schlichtheit in Form und Glasur betont. Der ovale Teller wird in plastischer Technik von Hand gefertigt, die Tasse ist aus grauer Steinmasse handgedreht und mit schwarzer Mattglasur glasiert, ergänzt durch Glasur mit Bronzeeffekt. Perfekte Größe für die Zubereitung einer Portion Kaffee in einer Kaffeemaschine.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-kafijas-kruze-015-l-skivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; kettle with strainer 0.9L + 2 cups 0.25 L + plate 32*27 cm', 'Dish set. Firing temperature 1250 °C. Decorated in the engraving technique using motifs of natural patterns. Glazed with a sand-colored matte effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Dish set. Firing temperature 1250 °C. Decorated in the engraving technique using motifs of natural patterns. Glazed with a sand-colored matte effect glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Dabas raksti, Komplekti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejkanna-1l-2-kruzes-04-l-skivis-30cm-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Wasserkocher mit Sieb 0,9 l + 2 Tassen 0,25 l + Teller 32 x 27 cm', 'Geschirrset. Brenntemperatur 1250 °C. Verziert in Gravurtechnik mit Motiven natürlicher Muster. Glasiert mit einer sandfarbenen Matteffektglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Geschirrset. Brenntemperatur 1250 °C. Verziert in Gravurtechnik mit Motiven natürlicher Muster. Glasiert mit einer sandfarbenen Matteffektglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Dabas raksti, Komplekti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejkanna-1l-2-kruzes-04-l-skivis-30cm-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; large bowl + 4 small ones', 'Made by hand in plastic technique from white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'Made by hand in plastic technique from white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'Dabas raksti, Komplekti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-liela-bloda-4-mazas';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; große Schüssel + 4 kleine', 'Handgefertigt in plastischer Technik aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Handgefertigt in plastischer Technik aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Dabas raksti, Komplekti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-liela-bloda-4-mazas';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; tea/coffee cup 0.25L + saucer', 'Set of dishes: Tea/coffee cup 0.25L + saucer. The mug is made by hand on a potter''s wheel from white stone mass. The saucer is made by hand using plastic technique. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'Set of dishes: Tea/coffee cup 0.25L + saucer. The mug is made by hand on a potter''s wheel from white stone mass. The saucer is made by hand using plastic technique. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-kruze-025l-apakstase';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Tee-/Kaffeetasse 0,25 l + Untertasse', 'Geschirrset: Tee-/Kaffeetasse 0,25 l + Untertasse. Der Becher wird von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Die Untertasse wird in Kunststofftechnik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Geschirrset: Tee-/Kaffeetasse 0,25 l + Untertasse. Der Becher wird von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Die Untertasse wird in Kunststofftechnik von Hand gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejas-kafijas-kruze-025l-apakstase';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set &#8211; teapot 0.5L + 2 glasses 120 ml + plate 27cm', 'The teapot and glasses are hand formed on the potter''s wheel from gray stoneware and partially glazed with a black matte glaze. The plate is made by hand using plastic technique. Firing temperature – 1250°C.', 'The teapot and glasses are hand formed on the potter''s wheel from gray stoneware and partially glazed with a black matte glaze. The plate is made by hand using plastic technique. Firing temperature – 1250°C.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejkanna-0-5l-2-glazes-120-ml-skivis-27cm-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset &#8211; Teekanne 0,5L + 2 Gläser 120 ml + Teller 27cm', 'Die Teekanne und die Gläser werden von Hand auf der Töpferscheibe aus grauem Steinzeug geformt und teilweise mit einer schwarzen, matten Glasur glasiert. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C.', 'Die Teekanne und die Gläser werden von Hand auf der Töpferscheibe aus grauem Steinzeug geformt und teilweise mit einer schwarzen, matten Glasur glasiert. Der Teller wird in plastischer Technik von Hand gefertigt. Brenntemperatur – 1250°C.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-tejkanna-0-5l-2-glazes-120-ml-skivis-27cm-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Glass 0.2L', 'Glass 0.2L. Crafted by hand on a potter''s wheel from gray stoneware. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with black matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Glass 0.2L. Crafted by hand on a potter''s wheel from gray stoneware. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with black matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-glaze-0-2l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Glas 0,2L', 'Glas 0,2L. Handgefertigt auf einer Töpferscheibe aus grauem Steingut. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit schwarzer Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Glas 0,2L. Handgefertigt auf einer Töpferscheibe aus grauem Steingut. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit schwarzer Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-glaze-0-2l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Heated kettle with strainer 1.5L', 'Heated kettle 1.5L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Heated kettle 1.5L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Melnā/svēpētā keramika, Tējkannas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-sildama-tejkanna-ar-sietinu-15l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Beheizter Wasserkocher mit Sieb, 1,5 l', 'Beheizter Wasserkocher 1,5 l. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Beheizter Wasserkocher 1,5 l. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Melnā/svēpētā keramika, Tējkannas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-sildama-tejkanna-ar-sietinu-15l-2';
