insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Serving plate in a gift box', 'The serving plate 26*22 cm is packed in wood shavings in a gift box. Made by hand in plastic technique from gray stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'The serving plate 26*22 cm is packed in wood shavings in a gift box. Made by hand in plastic technique from gray stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'Dabas raksti, Šķīvji', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-servejamais-skivis-davanu-kaste-4';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Servierteller in einer Geschenkbox', 'Der Servierteller 26*22 cm ist holzspänenverpackt in einer Geschenkbox. Handgefertigt in plastischer Technik aus grauer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Der Servierteller 26*22 cm ist holzspänenverpackt in einer Geschenkbox. Handgefertigt in plastischer Technik aus grauer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Dabas raksti, Šķīvji', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-servejamais-skivis-davanu-kaste-4';
