insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set &#8211; appetizer plate + sauce dish', 'The sauce pot is hand-crafted on a potter''s wheel from white stoneware. Plate 17*25 cm made by hand in plastic technique, decorated by hand in engraving technique. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'The sauce pot is hand-crafted on a potter''s wheel from white stoneware. Plate 17*25 cm made by hand in plastic technique, decorated by hand in engraving technique. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'RĀMUMS, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-komplekts-uzkodu-skivis-merces-trauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Stellen Sie &#8211; Vorspeisenteller + Soßenteller', 'Der Soßentopf wird auf einer Töpferscheibe aus weißem Steinzeug handgefertigt. Teller 17*25 cm, von Hand in plastischer Technik gefertigt, von Hand in Gravurtechnik verziert. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Der Soßentopf wird auf einer Töpferscheibe aus weißem Steinzeug handgefertigt. Teller 17*25 cm, von Hand in plastischer Technik gefertigt, von Hand in Gravurtechnik verziert. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'RĀMUMS, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-komplekts-uzkodu-skivis-merces-trauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set &#8211; snack/sauce dishes 4 pcs', 'The dishes are made by hand on the potter''s wheel from the white stone mass. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'The dishes are made by hand on the potter''s wheel from the white stone mass. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'RĀMUMS, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-komplekts-uzkodu-merces-trauki-4-gb';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Stellen Sie &#8211; Snack-/Saucenschalen 4-tlg', 'Das Geschirr wird von Hand auf der Töpferscheibe aus der weißen Steinmasse hergestellt. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Das Geschirr wird von Hand auf der Töpferscheibe aus der weißen Steinmasse hergestellt. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'RĀMUMS, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-komplekts-uzkodu-merces-trauki-4-gb';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set &#8211; tea/coffee cup 0.3L + plate', 'Tea/coffee mug 0.3L. Crafted by hand on a potter''s wheel from white stone mass. Plate 14*14 cm made by hand using plastic technique. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Tea/coffee mug 0.3L. Crafted by hand on a potter''s wheel from white stone mass. Plate 14*14 cm made by hand using plastic technique. Firing temperature 1250 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'RĀMUMS, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-komplekts-tejas-kafijas-kruze-03l-skivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Stellen Sie &#8211; Tee-/Kaffeetasse 0,3 l + Teller', 'Tee-/Kaffeebecher 0,3 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Teller 14*14 cm, handgefertigt in Kunststofftechnik. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Tee-/Kaffeebecher 0,3 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Teller 14*14 cm, handgefertigt in Kunststofftechnik. Brenntemperatur 1250 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'RĀMUMS, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-komplekts-tejas-kafijas-kruze-03l-skivis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set of 4 soup/pea bowls', 'Soup/pea bowl set. The bowls are made by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowls are decorated in engraving technique. Can be used in contact with food products, including wet products, in the microwave and oven. Hand washing is recommended for long term use.', 'Soup/pea bowl set. The bowls are made by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowls are decorated in engraving technique. Can be used in contact with food products, including wet products, in the microwave and oven. Hand washing is recommended for long term use.', 'Bļodas, Komplekti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-zupas-zirnu-blodu-komplekts-4-gb';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Set mit 4 Suppen-/Erbsenschalen', 'Suppen-/Erbsenschüssel-Set. Die Schalen werden von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schalen sind in Gravurtechnik verziert. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen.', 'Suppen-/Erbsenschüssel-Set. Die Schalen werden von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schalen sind in Gravurtechnik verziert. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen.', 'Bļodas, Komplekti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-zupas-zirnu-blodu-komplekts-4-gb';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set of beer cups 0.5L &#8211; 2 in a gift box 0.5L', 'Beer cups 0.5L. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Beer cups 0.5L. Crafted by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Krūzes, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-alus-kausu-05l-komplekts-davanu-kaste-05l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Set Bierbecher 0,5L &#8211; 2 in einer Geschenkbox 0,5L', 'Bierbecher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bierbecher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton gefertigt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Krūzes, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-alus-kausu-05l-komplekts-davanu-kaste-05l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Set of teaware: teapot 0.4L + 2 teacups', 'Tea set. From the ANAGAMA collection. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature 1300 °C. Natural ash glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Tea set. From the ANAGAMA collection. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature 1300 °C. Natural ash glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'ANAGAMA, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-trauku-komplekts-tejkanna-04l-tejas-pialas-2-gb';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Teegeschirr-Set: Teekanne 0,4 l + 2 Teetassen', 'Teeservice. Aus der ANAGAMA-Kollektion. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur 1300 °C. Natürliche Ascheglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Teeservice. Aus der ANAGAMA-Kollektion. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur 1300 °C. Natürliche Ascheglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'ANAGAMA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-trauku-komplekts-tejkanna-04l-tejas-pialas-2-gb';
