insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Soap dish', 'A soap dish with legs made by hand from white stone mass. Firing temperature 1250 °C. Easy to use and wash. Holes for water drainage help the soap to always be dry.', 'A soap dish with legs made by hand from white stone mass. Firing temperature 1250 °C. Easy to use and wash. Holes for water drainage help the soap to always be dry.', 'Trauki no akmens masas, ziepju trauki', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-ziepju-trauks-4';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Seifenschale', 'Eine handgefertigte Seifenschale mit Beinen aus weißer Steinmasse. Brenntemperatur 1250 °C. Einfach zu verwenden und zu waschen. Löcher für den Wasserablauf sorgen dafür, dass die Seife immer trocken bleibt.', 'Eine handgefertigte Seifenschale mit Beinen aus weißer Steinmasse. Brenntemperatur 1250 °C. Einfach zu verwenden und zu waschen. Löcher für den Wasserablauf sorgen dafür, dass die Seife immer trocken bleibt.', 'Trauki no akmens masas, ziepju trauki', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-ziepju-trauks-4';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Soap dish', 'Handcrafted from dark brown stone mass. Firing temperature 1050 °C. Easy to use and wash. The relief formation helps the soap to maintain a dry surface. The compact size will also fit well on small surfaces.', 'Handcrafted from dark brown stone mass. Firing temperature 1050 °C. Easy to use and wash. The relief formation helps the soap to maintain a dry surface. The compact size will also fit well on small surfaces.', 'Trauki no akmens masas, ziepju trauki', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-ziepju-trauks-kopija';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Seifenschale', 'Handgefertigt aus dunkelbrauner Steinmasse. Brenntemperatur 1050 °C. Einfach zu verwenden und zu waschen. Die Reliefbildung trägt dazu bei, dass die Seife eine trockene Oberfläche behält. Die kompakte Größe passt auch gut auf kleine Flächen.', 'Handgefertigt aus dunkelbrauner Steinmasse. Brenntemperatur 1050 °C. Einfach zu verwenden und zu waschen. Die Reliefbildung trägt dazu bei, dass die Seife eine trockene Oberfläche behält. Die kompakte Größe passt auch gut auf kleine Flächen.', 'Trauki no akmens masas, ziepju trauki', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-ziepju-trauks-kopija';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Soap dish', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/swept technique. Firing temperature 1050 °C. Easy to use and wash. Holes for water drainage help the soap to always be dry.', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/swept technique. Firing temperature 1050 °C. Easy to use and wash. Holes for water drainage help the soap to always be dry.', 'Melnā/svēpētā keramika, Ziepju trauki', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-ziepju-trauks-2';
