insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Soup bowl set &#8211; 4 pcs', 'Set of soup bowls - 4 pcs. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health, without harmful impurities.', 'Set of soup bowls - 4 pcs. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health, without harmful impurities.', 'Komplekti, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-zupas-blodu-komplekts';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Suppenschüssel-Set &#8211; 4 Stk', 'Set Suppentassen - 4-tlg. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend, ohne schädliche Verunreinigungen.', 'Set Suppentassen - 4-tlg. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend, ohne schädliche Verunreinigungen.', 'Komplekti, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-zupas-blodu-komplekts';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Soup bowls', 'Soup bowls 0.4 L Made by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with black matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Soup bowls 0.4 L Made by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "Monochrome". Glazed with black matte glaze. The glaze used is friendly to the environment and human health without harmful impurities.', 'Monohroms, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-zupas-blodas';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Suppenschüsseln', 'Suppenschüsseln 0,4 L Von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit schwarzer Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Suppenschüsseln 0,4 L Von Hand auf einer Töpferscheibe aus weißer Steinmasse gefertigt. Brenntemperatur – 1250°C. Aus der Kollektion „Monochrome“. Glasiert mit schwarzer Mattglasur. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Monohroms, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-zupas-blodas';
