insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Eintopfbehälter mit Deckel 4L', 'Eine Auflaufform mit Deckel. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C.', 'Eine Auflaufform mit Deckel. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C.', 'Bļodas, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-sautejamais-trauks-ar-vaku-4l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Sugar bowl in a gift box', 'Sugar bowl 0.4L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Sugar bowl 0.4L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Cukurtrauki, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Zuckerdose in einer Geschenkbox', 'Zuckerdose 0,4L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Zuckerdose 0,4L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Cukurtrauki, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Sugar bowl in a gift box', 'Sugar bowl 0.4L in a gift box with a window. Packed in wood shavings. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Sugar bowl 0.4L in a gift box with a window. Packed in wood shavings. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Cukurtrauki, Melnā/svēpētā keramika', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Zuckerdose in einer Geschenkbox', 'Zuckerdose 0,4L in einer Geschenkbox mit Sichtfenster. Verpackt in Holzspänen. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Zuckerdose 0,4L in einer Geschenkbox mit Sichtfenster. Verpackt in Holzspänen. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Cukurtrauki, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Sugar bowl in a gift box', 'Sugar bowl in a gift box with a window. Packed in wood shavings. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'Sugar bowl in a gift box with a window. Packed in wood shavings. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Can be washed in the dishwasher.', 'Cukurtrauki, Dabas raksti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Zuckerdose in einer Geschenkbox', 'Zuckerdose in einer Geschenkbox mit Sichtfenster. Verpackt in Holzspänen. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Zuckerdose in einer Geschenkbox mit Sichtfenster. Verpackt in Holzspänen. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Kann in der Spülmaschine gewaschen werden.', 'Cukurtrauki, Dabas raksti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-cukurtrauks-davanu-kaste';
