insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Sweets container 21.5cm', 'The dish is made by hand in the plastic technique from gray stone mass. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'The dish is made by hand in the plastic technique from gray stone mass. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'Melns un Zelts, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-saldumu-trauks-21-5cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Süßigkeitenbehälter 21,5 cm', 'Die Schale ist in plastischer Technik aus grauer Steinmasse handgefertigt. Verziert mit goldfarbenen Zeichnungen in Abziehbildtechnik. Brenntemperatur – 1250°C.', 'Die Schale ist in plastischer Technik aus grauer Steinmasse handgefertigt. Verziert mit goldfarbenen Zeichnungen in Abziehbildtechnik. Brenntemperatur – 1250°C.', 'Melns un Zelts, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-saldumu-trauks-21-5cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tableware set: 4 bowls + 4 plates', 'Tableware set: 4 bowls + 4 plates. Made by hand on a potter''s wheel and plastic technique from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. Can be used in contact with food products, including wet products, in the microwave and oven.', 'Tableware set: 4 bowls + 4 plates. Made by hand on a potter''s wheel and plastic technique from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. Can be used in contact with food products, including wet products, in the microwave and oven.', 'Bļodas, Komplekti', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-trauku-komplekts-4-blodas-4-skivji';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset: 4 Schüsseln + 4 Teller', 'Geschirrset: 4 Schüsseln + 4 Teller. Von Hand auf einer Töpferscheibe und plastischer Technik aus lettischem Ton hergestellt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden.', 'Geschirrset: 4 Schüsseln + 4 Teller. Von Hand auf einer Töpferscheibe und plastischer Technik aus lettischem Ton hergestellt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Kann in der Mikrowelle und im Ofen bei Kontakt mit Lebensmitteln, auch feuchten Produkten, verwendet werden.', 'Bļodas, Komplekti', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-trauku-komplekts-4-blodas-4-skivji';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tea/broth/soup cup 0.7L', 'Mug 0.7L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Mug 0.7L. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, Krūzes', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-buljona-zupas-kruze-0-7l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Brühe-/Suppenbecher 0,7 l', 'Becher 0,7L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Becher 0,7L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, Krūzes', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-buljona-zupas-kruze-0-7l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tea/coffee cup 0.25 L', 'The mug is hand formed on a potter''s wheel from gray stoneware and glazed with a turquoise blue luster glaze. Firing temperature – 1250°C. From the BLUE LAGOON collection.', 'The mug is hand formed on a potter''s wheel from gray stoneware and glazed with a turquoise blue luster glaze. Firing temperature – 1250°C. From the BLUE LAGOON collection.', 'Trauki no akmens masas, ZILĀ LAGŪNA', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-025-l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Kaffeetasse 0,25 L', 'Der Becher ist von Hand auf einer Töpferscheibe aus grauem Steingut geformt und mit einer türkisblauen Glanzglasur glasiert. Brenntemperatur – 1250°C. Aus der BLUE LAGOON-Kollektion.', 'Der Becher ist von Hand auf einer Töpferscheibe aus grauem Steingut geformt und mit einer türkisblauen Glanzglasur glasiert. Brenntemperatur – 1250°C. Aus der BLUE LAGOON-Kollektion.', 'Trauki no akmens masas, ZILĀ LAGŪNA', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-025-l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tea/coffee cup 0.45 L', 'The mug is made by hand on a potter''s wheel from gray stoneware and glazed with a black matte glaze. A bronze sheen of glaze on the upper edge. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'The mug is made by hand on a potter''s wheel from gray stoneware and glazed with a black matte glaze. A bronze sheen of glaze on the upper edge. Decorated with gold-colored drawings in the decal technique. Firing temperature – 1250°C.', 'Melns un Zelts, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-0-45-l-4';
