insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tea/coffee mug 0.25L', 'Tea/coffee mug 0.25L. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'Tea/coffee mug 0.25L. Crafted by hand on a potter''s wheel from white stone mass. Firing temperature – 1250°C. From the collection "GREY ROMANCE". Glazed with two intermingling glazes creating a blue-gray, romantic mood. The glaze used is friendly to the environment and human health without harmful impurities.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-025l-2';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Kaffeebecher 0,25 l', 'Tee-/Kaffeebecher 0,25 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Tee-/Kaffeebecher 0,25 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-025l-2';
