insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Kaffeebecher 0,5 l', 'Tee-/Kaffeebecher 0,5 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Tee-/Kaffeebecher 0,5 l. Handgefertigt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Aus der Kollektion „GREY ROMANCE“. Mit zwei ineinander übergehenden Glasuren glasiert, die eine blaugraue, romantische Stimmung erzeugen. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'PELĒKĀ ROMANTIKA, Trauki no akmens masas', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-05l-2';
