insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Kaffeebecher 0,5 l', 'Becher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Becher 0,5L. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Krūzes, Melnā/svēpētā keramika', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-tejas-kafijas-kruze-05l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tray 28 cm', 'Tray 29 cm. Made on a potter''s wheel of white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'Tray 29 cm. Made on a potter''s wheel of white stone mass. Firing temperature – 1250°C. The glaze used is friendly to the environment and human health without harmful impurities. Microwave safe, dishwasher safe.', 'Dabas raksti, LAVANDA', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-paplate-29-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tablett 28 cm', 'Tablett 29 cm. Hergestellt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Tablett 29 cm. Hergestellt auf einer Töpferscheibe aus weißer Steinmasse. Brenntemperatur – 1250°C. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Mikrowellengeeignet, spülmaschinenfest.', 'Dabas raksti, LAVANDA', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-paplate-29-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tray 30 cm', 'Tray 30 cm. Firing temperature 1250 °C. Glazed with bright light effect glaze. From the collection "LIGHT". The glaze used is friendly to the environment and human health without harmful impurities.', 'Tray 30 cm. Firing temperature 1250 °C. Glazed with bright light effect glaze. From the collection "LIGHT". The glaze used is friendly to the environment and human health without harmful impurities.', 'Bļodas, GAISMA', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'cepli-paplate-30-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tablett 30 cm', 'Tablett 30 cm. Brenntemperatur 1250 °C. Glasiert mit heller Lichteffektglasur. Aus der Kollektion „LIGHT“. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Tablett 30 cm. Brenntemperatur 1250 °C. Glasiert mit heller Lichteffektglasur. Aus der Kollektion „LIGHT“. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.', 'Bļodas, GAISMA', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'cepli-paplate-30-cm';
