insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl', 'Clay bowl, for domestic use. Dimensions: height: 14 cm, diameter: 30 cm. The colors and sizes of the bowls are as diverse as possible, sizes in diameter from 8 cm to 40 cm, height up to 25 cm. If you want a bowl of a different shape and color that is not available ready-made in the workshop, it is possible to make the desired one within 2 weeks from the moment of ordering.', 'Clay bowl, for domestic use. Dimensions: height: 14 cm, diameter: 30 cm. The colors and sizes of the bowls are as diverse as possible, sizes in diameter from 8 cm to 40 cm, height up to 25 cm. If you want a bowl of a different shape and color that is not available ready-made in the workshop, it is possible to make the desired one within 2 weeks from the moment of ordering.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-b-oda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Schüssel', 'Tonschale für den Hausgebrauch. Maße: Höhe: 14 cm, Durchmesser: 30 cm. Die Farben und Größen der Schalen sind möglichst vielfältig, Größen im Durchmesser von 8 cm bis 40 cm, Höhe bis 25 cm. Wenn Sie eine Schüssel in einer anderen Form und Farbe wünschen, die in der Werkstatt nicht fertig verfügbar ist, ist es möglich, die gewünschte Schüssel innerhalb von 2 Wochen ab dem Zeitpunkt der Bestellung anzufertigen.', 'Tonschale für den Hausgebrauch. Maße: Höhe: 14 cm, Durchmesser: 30 cm. Die Farben und Größen der Schalen sind möglichst vielfältig, Größen im Durchmesser von 8 cm bis 40 cm, Höhe bis 25 cm. Wenn Sie eine Schüssel in einer anderen Form und Farbe wünschen, die in der Werkstatt nicht fertig verfügbar ist, ist es möglich, die gewünschte Schüssel innerhalb von 2 Wochen ab dem Zeitpunkt der Bestellung anzufertigen.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-b-oda';
