insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Butter dish "like butter"', 'Hand-glued, fired in a pit-type wood-fired oven. No glaze is used. The black, silver, bronze shade of our dishes is achieved in the firing-reduction process. With that, these dishes are also unique and admirable. It''s a game of fire with clay. It is like a miracle of birth, which is impossible to predict in advance.         biezaart.com/veikals/category/keramika/', 'Hand-glued, fired in a pit-type wood-fired oven. No glaze is used. The black, silver, bronze shade of our dishes is achieved in the firing-reduction process. With that, these dishes are also unique and admirable. It''s a game of fire with clay. It is like a miracle of birth, which is impossible to predict in advance.         biezaart.com/veikals/category/keramika/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sviesta-trauks-k-pa-sviestu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Butterdose „wie Butter“', 'Von Hand geklebt, im Holzofen gebrannt. Es wird keine Glasur verwendet. Der Schwarz-, Silber- und Bronzeton unseres Geschirrs wird durch das Brenn-Reduktionsverfahren erreicht. Damit sind auch diese Gerichte einzigartig und bewundernswert. Es ist ein Spiel zwischen Feuer und Ton. Es ist wie ein Geburtswunder, das man nicht im Voraus vorhersagen kann.         biezaart.com/veikals/category/keramika/', 'Von Hand geklebt, im Holzofen gebrannt. Es wird keine Glasur verwendet. Der Schwarz-, Silber- und Bronzeton unseres Geschirrs wird durch das Brenn-Reduktionsverfahren erreicht. Damit sind auch diese Gerichte einzigartig und bewundernswert. Es ist ein Spiel zwischen Feuer und Ton. Es ist wie ein Geburtswunder, das man nicht im Voraus vorhersagen kann.         biezaart.com/veikals/category/keramika/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sviesta-trauks-k-pa-sviestu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Cake plate / Cake plate', 'Cake plate / Cake plate', 'Cake plate / Cake plate', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-k-ku-vis-cake-plate';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Kuchenplatte / Kuchenplatte', 'Kuchenplatte / Kuchenplatte', 'Kuchenplatte / Kuchenplatte', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-k-ku-vis-cake-plate';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Candle holder/ cup', 'A candlestick that is a cup after the holiday. As Cinderella turns into a princess, as a carriage into a pumpkin, a candle holder into a cup, a glass of water.  The design of the mug is interesting with a medallion of the symbol of strength - it will protect, strengthen and make everyday life more beautiful :)', 'A candlestick that is a cup after the holiday. As Cinderella turns into a princess, as a carriage into a pumpkin, a candle holder into a cup, a glass of water.  The design of the mug is interesting with a medallion of the symbol of strength - it will protect, strengthen and make everyday life more beautiful :)', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-turs-kr-ze';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Kerzenhalter/Tasse', 'Ein Kerzenhalter, der eine Tasse nach dem Feiertag ist. Wie sich Aschenputtel in eine Prinzessin verwandelt, wie eine Kutsche in einen Kürbis, ein Kerzenhalter in eine Tasse, ein Glas Wasser.  Interessant ist das Design des Bechers mit einem Medaillon des Symbols der Stärke – es schützt, stärkt und macht den Alltag schöner :)', 'Ein Kerzenhalter, der eine Tasse nach dem Feiertag ist. Wie sich Aschenputtel in eine Prinzessin verwandelt, wie eine Kutsche in einen Kürbis, ein Kerzenhalter in eine Tasse, ein Glas Wasser.  Interessant ist das Design des Bechers mit einem Medaillon des Symbols der Stärke – es schützt, stärkt und macht den Alltag schöner :)', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-turs-kr-ze';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Candle houses', 'Candle houses with their light radiation will bring a cozy and warm atmosphere to every house and hut :)', 'Candle houses with their light radiation will bring a cozy and warm atmosphere to every house and hut :)', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-u-m-ji-as';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Kerzenhäuser', 'Kerzenhäuser bringen mit ihrer Lichtstrahlung eine gemütliche und warme Atmosphäre in jedes Haus und jede Hütte :)', 'Kerzenhäuser bringen mit ihrer Lichtstrahlung eine gemütliche und warme Atmosphäre in jedes Haus und jede Hütte :)', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-u-m-ji-as';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Candlestick', 'White porcelain openwork candle holder with tiny gold dots. The lamp will bring coziness and a festive mood to your home, even if winter does not spoil with snow. The snowflake can also be used as a container for candy or sweets. The candlestick is packed in a box with a transparent cover. Size: diameter = 12 cm; h = 5 cm.', 'White porcelain openwork candle holder with tiny gold dots. The lamp will bring coziness and a festive mood to your home, even if winter does not spoil with snow. The snowflake can also be used as a container for candy or sweets. The candlestick is packed in a box with a transparent cover. Size: diameter = 12 cm; h = 5 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-turis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Leuchter', 'Durchbrochener Kerzenhalter aus weißem Porzellan mit winzigen Goldpunkten. Die Lampe bringt Gemütlichkeit und festliche Stimmung in Ihr Zuhause, auch wenn der Winter nicht durch Schnee verdorben wird. Die Schneeflocke kann auch als Behälter für Bonbons oder Bonbons verwendet werden. Der Kerzenhalter ist in einer Box mit transparentem Deckel verpackt. Größe: Durchmesser = 12 cm; h = 5 cm.', 'Durchbrochener Kerzenhalter aus weißem Porzellan mit winzigen Goldpunkten. Die Lampe bringt Gemütlichkeit und festliche Stimmung in Ihr Zuhause, auch wenn der Winter nicht durch Schnee verdorben wird. Die Schneeflocke kann auch als Behälter für Bonbons oder Bonbons verwendet werden. Der Kerzenhalter ist in einer Box mit transparentem Deckel verpackt. Größe: Durchmesser = 12 cm; h = 5 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sve-turis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Clay mug with Forest pattern', 'Formed using the gluing technique, polished and fired in a wood-fired oven. At the end of the firing, it is swept (reduced), resulting in a black metallic work color. No glazes or other additives are used. Pure clay.   Available in size L - 30 eur and XL 35 eur. Delivery in Latvia with a parcel without extra charge for orders over 40 EUR.  Height: XL 13-14 cm L 11-13 cm Diameter 9-10 cm Volume XL 500-600 ml L 350-450 ml The most convenient way to order - http://www.ozolinspottery.com/veikals/category/kruzes/', 'Formed using the gluing technique, polished and fired in a wood-fired oven. At the end of the firing, it is swept (reduced), resulting in a black metallic work color. No glazes or other additives are used. Pure clay.   Available in size L - 30 eur and XL 35 eur. Delivery in Latvia with a parcel without extra charge for orders over 40 EUR.  Height: XL 13-14 cm L 11-13 cm Diameter 9-10 cm Volume XL 500-600 ml L 350-450 ml The most convenient way to order - http://www.ozolinspottery.com/veikals/category/kruzes/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-kr-ze-ar-me-a-rakstu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tonbecher mit Waldmuster', 'Mit der Klebetechnik geformt, poliert und im Holzofen gebrannt. Am Ende des Brandes wird es gewischt (reduziert), wodurch eine schwarze metallische Arbeitsfarbe entsteht. Es werden keine Glasuren oder andere Zusatzstoffe verwendet. Reiner Ton.   Erhältlich in Größe L - 30 Euro und XL 35 Euro. Lieferung in Lettland mit einem Paket ohne Aufpreis für Bestellungen über 40 EUR.  Höhe: XL 13–14 cm L 11–13 cm Durchmesser 9–10 cm Volumen XL 500–600 ml L 350–450 ml Die bequemste Art zu bestellen – http://www.ozolinspottery.com/veikals/category/kruzes/', 'Mit der Klebetechnik geformt, poliert und im Holzofen gebrannt. Am Ende des Brandes wird es gewischt (reduziert), wodurch eine schwarze metallische Arbeitsfarbe entsteht. Es werden keine Glasuren oder andere Zusatzstoffe verwendet. Reiner Ton.   Erhältlich in Größe L - 30 Euro und XL 35 Euro. Lieferung in Lettland mit einem Paket ohne Aufpreis für Bestellungen über 40 EUR.  Höhe: XL 13–14 cm L 11–13 cm Durchmesser 9–10 cm Volumen XL 500–600 ml L 350–450 ml Die bequemste Art zu bestellen – http://www.ozolinspottery.com/veikals/category/kruzes/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-kr-ze-ar-me-a-rakstu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Clay mug with Rising Sun pattern', 'Formed using the gluing technique, polished and fired in a wood-fired oven. At the end of the firing, it is swept (reduced), resulting in a black metallic work color. No glazes or other additives are used. Pure clay.   Available in size L - 30 eur and XL 35 eur. Delivery in Latvia with a parcel without extra charge for orders over 40 EUR.  Height: XL 13-14 cm L 11-13 cm Diameter 9-10 cm Volume XL 500-600 ml L 350-450 ml The most convenient way to order - http://www.ozolinspottery.com/veikals/category/kruzes/', 'Formed using the gluing technique, polished and fired in a wood-fired oven. At the end of the firing, it is swept (reduced), resulting in a black metallic work color. No glazes or other additives are used. Pure clay.   Available in size L - 30 eur and XL 35 eur. Delivery in Latvia with a parcel without extra charge for orders over 40 EUR.  Height: XL 13-14 cm L 11-13 cm Diameter 9-10 cm Volume XL 500-600 ml L 350-450 ml The most convenient way to order - http://www.ozolinspottery.com/veikals/category/kruzes/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-kr-ze-ar-austo-s-saules-rakstu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tonbecher mit Muster der aufgehenden Sonne', 'Mit der Klebetechnik geformt, poliert und im Holzofen gebrannt. Am Ende des Brandes wird es gewischt (reduziert), wodurch eine schwarze metallische Arbeitsfarbe entsteht. Es werden keine Glasuren oder andere Zusatzstoffe verwendet. Reiner Ton.   Erhältlich in Größe L - 30 Euro und XL 35 Euro. Lieferung in Lettland mit einem Paket ohne Aufpreis für Bestellungen über 40 EUR.  Höhe: XL 13–14 cm L 11–13 cm Durchmesser 9–10 cm Volumen XL 500–600 ml L 350–450 ml Die bequemste Art zu bestellen – http://www.ozolinspottery.com/veikals/category/kruzes/', 'Mit der Klebetechnik geformt, poliert und im Holzofen gebrannt. Am Ende des Brandes wird es gewischt (reduziert), wodurch eine schwarze metallische Arbeitsfarbe entsteht. Es werden keine Glasuren oder andere Zusatzstoffe verwendet. Reiner Ton.   Erhältlich in Größe L - 30 Euro und XL 35 Euro. Lieferung in Lettland mit einem Paket ohne Aufpreis für Bestellungen über 40 EUR.  Höhe: XL 13–14 cm L 11–13 cm Durchmesser 9–10 cm Volumen XL 500–600 ml L 350–450 ml Die bequemste Art zu bestellen – http://www.ozolinspottery.com/veikals/category/kruzes/', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-kr-ze-ar-austo-s-saules-rakstu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Clay whistler', 'Clay whistler with angobe pattern and glazed whistle. Clear sound, two playable holes. Size 5-6 cm.', 'Clay whistler with angobe pattern and glazed whistle. Clear sound, two playable holes. Size 5-6 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-svilpaunieks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Clay Whistler', 'Tonpfeife mit Angobemuster und glasierter Pfeife. Klarer Klang, zwei spielbare Löcher. Größe 5-6 cm.', 'Tonpfeife mit Angobemuster und glasierter Pfeife. Klarer Klang, zwei spielbare Löcher. Größe 5-6 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-svilpaunieks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Clay whistler tuned', 'Clay whistler tuned A4, size 130x60x80mm, or G4, size 150x65x85mm.', 'Clay whistler tuned A4, size 130x60x80mm, or G4, size 150x65x85mm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-svilpaunieks-ska-otais';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Clay Whistler gestimmt', 'Clay Whistler gestimmt A4, Größe 130x60x80mm, oder G4, Größe 150x65x85mm.', 'Clay Whistler gestimmt A4, Größe 130x60x80mm, oder G4, Größe 150x65x85mm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-m-la-svilpaunieks-ska-otais';
