insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish - SUNFLOWER', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Scented Pottery. Red clay mass d-26cm, h-6cm Handmade Free delivery in Riga/Riga', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Scented Pottery. Red clay mass d-26cm, h-6cm Handmade Free delivery in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Gericht - SONNENBLUME', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarze/duftende Keramik. Masse aus rotem Ton, D-26 cm, H-6 cm, handgefertigt. Kostenlose Lieferung in Riga/Riga', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarze/duftende Keramik. Masse aus rotem Ton, D-26 cm, H-6 cm, handgefertigt. Kostenlose Lieferung in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-3';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish - SUNFLOWER', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Sweated/White/ ceramics. Red, white clay mass d-8cm, h-2cm Handmade Free delivery in Riga/Riga', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Sweated/White/ ceramics. Red, white clay mass d-8cm, h-2cm Handmade Free delivery in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-4';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Gericht - SONNENBLUME', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarz/Geschwitzt/Weiß/Keramik. Rote, weiße Tonmasse D-8cm, H-2cm Handgemacht Kostenlose Lieferung in Riga/Riga', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarz/Geschwitzt/Weiß/Keramik. Rote, weiße Tonmasse D-8cm, H-2cm Handgemacht Kostenlose Lieferung in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-4';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish - SUNFLOWER', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Scented Pottery. Red clay mass d-17cm, h-6cm Handmade Free delivery in Riga/Riga', 'Sunflowers - are often associated with warmth, kindness and positive energy, they give joy. Black/Scented Pottery. Red clay mass d-17cm, h-6cm Handmade Free delivery in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-5';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Gericht - SONNENBLUME', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarze/duftende Keramik. Masse aus rotem Ton, D-17 cm, H-6 cm, handgefertigt. Kostenlose Lieferung in Riga/Riga', 'Sonnenblumen – werden oft mit Wärme, Freundlichkeit und positiver Energie assoziiert, sie schenken Freude. Schwarze/duftende Keramik. Masse aus rotem Ton, D-17 cm, H-6 cm, handgefertigt. Kostenlose Lieferung in Riga/Riga', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauks-saulespu-e-5';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish - bull', 'Taurus - the symbol of the coming year!  The dish will be useful both as a candle holder and as a place to put sweets, nuts or jewelry.  We can also wrap it as a gift!', 'Taurus - the symbol of the coming year!  The dish will be useful both as a candle holder and as a place to put sweets, nuts or jewelry.  We can also wrap it as a gift!', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauci-v-rs-tis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Gericht - Bulle', 'Stier – das Symbol des kommenden Jahres!  Die Schale eignet sich sowohl als Kerzenhalter als auch als Ablage für Süßigkeiten, Nüsse oder Schmuck.  Wir können es auch als Geschenk verpacken!', 'Stier – das Symbol des kommenden Jahres!  Die Schale eignet sich sowohl als Kerzenhalter als auch als Ablage für Süßigkeiten, Nüsse oder Schmuck.  Wir können es auch als Geschenk verpacken!', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauci-v-rs-tis';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dish set.', 'Tableware set: 4 bowls + 4 plates. The bowls are made by hand on a potter''s wheel, and the plates are made by hand in the plastic technique from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowls are decorated in engraving technique.  Can be used in contact with food products, including wet ones, in microwave ovens and ovens. Hand washing is recommended for long-term use. Dimensions: Bowl: diam. 14 cm, h 7 cm, volume 0.45L, weight 0.34 kg; Plate: diam. 20.5 cm, weight 0.38 kg', 'Tableware set: 4 bowls + 4 plates. The bowls are made by hand on a potter''s wheel, and the plates are made by hand in the plastic technique from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The bowls are decorated in engraving technique.  Can be used in contact with food products, including wet ones, in microwave ovens and ovens. Hand washing is recommended for long-term use. Dimensions: Bowl: diam. 14 cm, h 7 cm, volume 0.45L, weight 0.34 kg; Plate: diam. 20.5 cm, weight 0.38 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauku-komplekts';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Geschirrset.', 'Geschirrset: 4 Schüsseln + 4 Teller. Die Schalen werden von Hand auf einer Töpferscheibe hergestellt, und die Teller werden von Hand in der plastischen Technik aus lettischem Ton hergestellt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schalen sind in Gravurtechnik verziert.  Kann in Kontakt mit Lebensmitteln, auch nassen, in Mikrowellenherden und Öfen verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen. Abmessungen: Schüssel: Durchm. 14 cm, H 7 cm, Volumen 0,45 l, Gewicht 0,34 kg; Platte: Durchm. 20,5 cm, Gewicht 0,38 kg', 'Geschirrset: 4 Schüsseln + 4 Teller. Die Schalen werden von Hand auf einer Töpferscheibe hergestellt, und die Teller werden von Hand in der plastischen Technik aus lettischem Ton hergestellt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Schalen sind in Gravurtechnik verziert.  Kann in Kontakt mit Lebensmitteln, auch nassen, in Mikrowellenherden und Öfen verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen. Abmessungen: Schüssel: Durchm. 14 cm, H 7 cm, Volumen 0,45 l, Gewicht 0,34 kg; Platte: Durchm. 20,5 cm, Gewicht 0,38 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-trauku-komplekts';
