insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Double clay stick', 'Double clay stick, can play melody along with bourdon sound. The tuning is in B major (G). A textile case is included.', 'Double clay stick, can play melody along with bourdon sound. The tuning is in B major (G). A textile case is included.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-dubult-m-la-stabule';
