insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Flames', 'Flames - beautiful candlesticks, for both large and smaller candles. Available in different colors and sizes.', 'Flames - beautiful candlesticks, for both large and smaller candles. Available in different colors and sizes.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-liesmi-as';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Flammen', 'Flames – wunderschöne Kerzenständer, sowohl für große als auch für kleinere Kerzen. Erhältlich in verschiedenen Farben und Größen.', 'Flames – wunderschöne Kerzenständer, sowohl für große als auch für kleinere Kerzen. Erhältlich in verschiedenen Farben und Größen.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-liesmi-as';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Fruit plate with ginkgo leaf motif', 'The fruit plate is made of white clay and decorated with a blue ginkgo leaf motif made in the underglaze technique. The vessel is covered with a bright, transparent glaze and fired at a temperature of 1050C. The glaze has the property of creating a network of small cracks, which gives the dishes an ancient feel, but does not reduce functionality. Size: diameter 28 cm.', 'The fruit plate is made of white clay and decorated with a blue ginkgo leaf motif made in the underglaze technique. The vessel is covered with a bright, transparent glaze and fired at a temperature of 1050C. The glaze has the property of creating a network of small cracks, which gives the dishes an ancient feel, but does not reduce functionality. Size: diameter 28 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-aug-u-vis-ar-ginka-lapu-mot-vu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Obstteller mit Ginkgoblatt-Motiv', 'Der Obstteller ist aus weißem Ton gefertigt und mit einem blauen Ginkgoblattmotiv in Unterglasurtechnik verziert. Das Gefäß ist mit einer hellen, transparenten Glasur überzogen und bei einer Temperatur von 1050 °C gebrannt. Die Glasur hat die Eigenschaft, ein Netzwerk aus kleinen Rissen zu bilden, was dem Geschirr ein antikes Aussehen verleiht, die Funktionalität jedoch nicht beeinträchtigt. Größe: Durchmesser 28 cm.', 'Der Obstteller ist aus weißem Ton gefertigt und mit einem blauen Ginkgoblattmotiv in Unterglasurtechnik verziert. Das Gefäß ist mit einer hellen, transparenten Glasur überzogen und bei einer Temperatur von 1050 °C gebrannt. Die Glasur hat die Eigenschaft, ein Netzwerk aus kleinen Rissen zu bilden, was dem Geschirr ein antikes Aussehen verleiht, die Funktionalität jedoch nicht beeinträchtigt. Größe: Durchmesser 28 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-aug-u-vis-ar-ginka-lapu-mot-vu';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Gentleman''s set', 'Gentleman''s set - snack plate and four glasses. It''s like a start button and the adventures can begin.  plate/board 19x19cm cups - delicious size for everyone according to their strength and needs', 'Gentleman''s set - snack plate and four glasses. It''s like a start button and the adventures can begin.  plate/board 19x19cm cups - delicious size for everyone according to their strength and needs', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-d-entelme-a-komplekti';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Gentleman-Set', 'Herrenset - Snackteller und vier Gläser. Es ist wie ein Startknopf und die Abenteuer können beginnen.  Teller/Brett 19x19cm Tassen – leckere Größe für jeden, je nach Stärke und Bedarf', 'Herrenset - Snackteller und vier Gläser. Es ist wie ein Startknopf und die Abenteuer können beginnen.  Teller/Brett 19x19cm Tassen – leckere Größe für jeden, je nach Stärke und Bedarf', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-d-entelme-a-komplekti';
