insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Ring holder cat', 'The ring holder is made of white clay, painted with blue pigment. We offer striped and spotted cats. Size including tail - 14 cm.', 'The ring holder is made of white clay, painted with blue pigment. We offer striped and spotted cats. Size including tail - 14 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-ka-is-gredzenu-tur-t-js';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Ringhalter Katze', 'Der Ringhalter ist aus weißem Ton gefertigt und mit blauem Pigment bemalt. Wir bieten gestreifte und gefleckte Katzen an. Größe inklusive Schwanz - 14 cm.', 'Der Ringhalter ist aus weißem Ton gefertigt und mit blauem Pigment bemalt. Wir bieten gestreifte und gefleckte Katzen an. Größe inklusive Schwanz - 14 cm.', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-ka-is-gredzenu-tur-t-js';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Routes', 'in the small souvenir cups you can put a small piece of cotton wool on which you can add perfume oil (aromatherapy)', 'in the small souvenir cups you can put a small piece of cotton wool on which you can add perfume oil (aromatherapy)', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-rotas';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Routen', 'In die kleinen Souvenirbecher können Sie ein kleines Stück Watte legen, auf das Sie Parfümöl geben können (Aromatherapie).', 'In die kleinen Souvenirbecher können Sie ein kleines Stück Watte legen, auf das Sie Parfümöl geben können (Aromatherapie).', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-rotas';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Salad bowl', 'Salad bowl. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The inside of the bowl is covered with white angoba and decorated in the engraving technique. The glaze used is friendly to the environment and human health, without harmful impurities. It can be used in contact with food products, including wet ones, in microwave ovens and ovens. Hand washing is recommended for long-term use. Dimensions: Diameter: 24 cm, Height: 10 cm, Volume: 2 L, Weight: 1 kg', 'Salad bowl. Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. The inside of the bowl is covered with white angoba and decorated in the engraving technique. The glaze used is friendly to the environment and human health, without harmful impurities. It can be used in contact with food products, including wet ones, in microwave ovens and ovens. Hand washing is recommended for long-term use. Dimensions: Diameter: 24 cm, Height: 10 cm, Volume: 2 L, Weight: 1 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sal-tu-b-oda';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Salatschüssel', 'Salatschüssel. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Innenseite der Schale ist mit weißem Angoba überzogen und in Gravurtechnik verziert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend, ohne schädliche Verunreinigungen. Es kann in Mikrowellenherden und Öfen in Kontakt mit Lebensmitteln, auch nassen, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen. Maße: Durchmesser: 24 cm, Höhe: 10 cm, Volumen: 2 l, Gewicht: 1 kg', 'Salatschüssel. Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Die Innenseite der Schale ist mit weißem Angoba überzogen und in Gravurtechnik verziert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend, ohne schädliche Verunreinigungen. Es kann in Mikrowellenherden und Öfen in Kontakt mit Lebensmitteln, auch nassen, verwendet werden. Bei längerem Gebrauch wird Handwäsche empfohlen. Maße: Durchmesser: 24 cm, Höhe: 10 cm, Volumen: 2 l, Gewicht: 1 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-sal-tu-b-oda';
