insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Sugarcane', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. Decorated in the engraving technique using motifs of Latvian characters. Sun sign - a symbol of eternal movement, life and immortality. For soul harmony and balance. The inside of the dish is glazed. The glaze used is friendly to the environment and human health without harmful impurities. Hand washing is recommended for long-term use. Dimensions: Diameter: 9.5 cm Height with cap: 10 cm Volume: 0.4 L Weight: 0.43 kg', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire kiln in the black/smoke technique. Firing temperature 1050 °C. Decorated in the engraving technique using motifs of Latvian characters. Sun sign - a symbol of eternal movement, life and immortality. For soul harmony and balance. The inside of the dish is glazed. The glaze used is friendly to the environment and human health without harmful impurities. Hand washing is recommended for long-term use. Dimensions: Diameter: 9.5 cm Height with cap: 10 cm Volume: 0.4 L Weight: 0.43 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-cukurtrauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Zuckerrohr', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Verziert in Gravurtechnik mit Motiven lettischer Schriftzeichen. Sonnenzeichen – ein Symbol für ewige Bewegung, Leben und Unsterblichkeit. Für Seelenharmonie und Ausgeglichenheit. Die Innenseite der Schale ist glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Bei längerem Gebrauch wird Handwäsche empfohlen. Maße: Durchmesser: 9,5 cm, Höhe mit Deckel: 10 cm, Volumen: 0,4 l, Gewicht: 0,43 kg', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Rauchtechnik gebrannt. Brenntemperatur 1050 °C. Verziert in Gravurtechnik mit Motiven lettischer Schriftzeichen. Sonnenzeichen – ein Symbol für ewige Bewegung, Leben und Unsterblichkeit. Für Seelenharmonie und Ausgeglichenheit. Die Innenseite der Schale ist glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen. Bei längerem Gebrauch wird Handwäsche empfohlen. Maße: Durchmesser: 9,5 cm, Höhe mit Deckel: 10 cm, Volumen: 0,4 l, Gewicht: 0,43 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-cukurtrauks';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tall garlic dish', 'Diameter / Diameter: 11cm Height / Height: 16cm', 'Diameter / Diameter: 11cm Height / Height: 16cm', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-garais-iploku-trauks-tall-garlic-dish';
