insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Tea/coffee cup 0.4L', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. Decorated in engraving technique, using motifs of Latvian characters. Sun sign - a symbol of eternal movement, life and immortality. For soul harmony and balance. The inside of the cup is glazed. The glaze used is friendly to the environment and human health without harmful impurities.           Dimensions: Diameter: 10 cm Height: 10 cm Volume: 0.4L Weight: 0.3 kg', 'Formed by hand on a potter''s wheel from Latvian clay and fired in an open fire oven in the black/scented technique. Firing temperature 1050 °C. Decorated in engraving technique, using motifs of Latvian characters. Sun sign - a symbol of eternal movement, life and immortality. For soul harmony and balance. The inside of the cup is glazed. The glaze used is friendly to the environment and human health without harmful impurities.           Dimensions: Diameter: 10 cm Height: 10 cm Volume: 0.4L Weight: 0.3 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-t-jas-kafijas-kr-ze-0-4l';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Tee-/Kaffeetasse 0,4 l', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Verziert in Gravurtechnik mit Motiven lettischer Schriftzeichen. Sonnenzeichen – ein Symbol für ewige Bewegung, Leben und Unsterblichkeit. Für Seelenharmonie und Ausgeglichenheit. Die Innenseite der Tasse ist glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.           Abmessungen: Durchmesser: 10 cm, Höhe: 10 cm, Volumen: 0,4 l, Gewicht: 0,3 kg', 'Von Hand auf einer Töpferscheibe aus lettischem Ton geformt und in einem offenen Feuerofen in der Schwarz-/Dufttechnik gebrannt. Brenntemperatur 1050 °C. Verziert in Gravurtechnik mit Motiven lettischer Schriftzeichen. Sonnenzeichen – ein Symbol für ewige Bewegung, Leben und Unsterblichkeit. Für Seelenharmonie und Ausgeglichenheit. Die Innenseite der Tasse ist glasiert. Die verwendete Glasur ist umweltfreundlich und gesundheitsschonend ohne schädliche Verunreinigungen.           Abmessungen: Durchmesser: 10 cm, Höhe: 10 cm, Volumen: 0,4 l, Gewicht: 0,3 kg', 'Clay ceramics', 'Clay', 'Handmade pottery' from public.products pr where pr.slug = 'latvijas-labumu-tirgus-mals-t-jas-kafijas-kr-ze-0-4l';
