insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Überwurf aus Leinen und Wolle, 95 x 205 cm', 'Weicher und sehr warmer handgewebter Überwurf aus Leinen und hochwertiger Wollmischung. Ein tolles Accessoire, das Sie sich an kühlen Abenden um die Schultern legen können. ---geteilt--- Farbe: Sand + Braun Abmessungen: Breite 95 cm, Länge 205 cm Zusammensetzung: 35 % Leinen, 30 % Alpaka, 25 % Merino, 10 % Polyamid Produktreferenz: 2x2 Grantr+Creme/Wolle+G3 platzieren Pflegehinweise: Handwäsche (max. 30 °C) oder chemische Reinigung. Da dieser Stoff zu 100 % handgefertigt ist, kann es zu Knoten oder natürlichen Unebenheiten kommen. Das Kissen auf dem Bild kann im Bereich Kissen erworben werden. Hinweis: Produkte können individuell angepasst werden, bitte kontaktieren Sie uns! STUDIO NATURAL HANDGEFERTIGT IN LETTLAND', 'Weicher und sehr warmer handgewebter Überwurf aus Leinen und hochwertiger Wollmischung. Ein tolles Accessoire, das Sie sich an kühlen Abenden um die Schultern legen können. ---geteilt--- Farbe: Sand + Braun Abmessungen: Breite 95 cm, Länge 205 cm Zusammensetzung: 35 % Leinen, 30 % Alpaka, 25 % Merino, 10 % Polyamid Produktreferenz: 2x2 Grantr+Creme/Wolle+G3 platzieren Pflegehinweise: Handwäsche (max. 30 °C) oder chemische Reinigung. Da dieser Stoff zu 100 % handgefertigt ist, kann es zu Knoten oder natürlichen Unebenheiten kommen. Das Kissen auf dem Bild kann im Bereich Kissen erworben werden. Hinweis: Produkte können individuell angepasst werden, bitte kontaktieren Sie uns! STUDIO NATURAL HANDGEFERTIGT IN LETTLAND', 'dev.Throw', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'studio-natural-dev-95x205-cm-place-2x2-grantr';
