insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Linen cashmere throw in gray 135x200', 'Soft and warm handwoven cashmere throw detailed with hand twisted fringes. It can also be used as a blanket scarf. A great accessory to put around your shoulders on chilly evenings. ---split--- Color: Grey Dimensions: length 135m, width 200cm Composition: 45% cashmere, 25% mohair, 20% silk, 10% viscose Product reference: TR Cashmere +puder + mistr brown metaic + FR Care instructions: Hand wash (max 30°C) or dry clean. Delicate detergent recommended. Iron at low temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. Warning: Product color may slightly vary due to photographic lighting sources or your monitor settings. Light gray throw in the photo can be purchased in the throws section . Note: Products can be customized, please contact us!', 'Soft and warm handwoven cashmere throw detailed with hand twisted fringes. It can also be used as a blanket scarf. A great accessory to put around your shoulders on chilly evenings. ---split--- Color: Grey Dimensions: length 135m, width 200cm Composition: 45% cashmere, 25% mohair, 20% silk, 10% viscose Product reference: TR Cashmere +puder + mistr brown metaic + FR Care instructions: Hand wash (max 30°C) or dry clean. Delicate detergent recommended. Iron at low temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. Warning: Product color may slightly vary due to photographic lighting sources or your monitor settings. Light gray throw in the photo can be purchased in the throws section . Note: Products can be customized, please contact us!', 'dev.Throw', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'studio-natural-linen-cashmere-throw-in-gray-135x200';
