insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Linen napkin Aina in ivory 40x40 cm', 'Elegant ivory sheer napkin, hand woven from premium linen and finished with a delicate handmade hemstitch. Decorative and practical element for a festive table. ---split--- Color: ivory Dimensions: w idth 40cm, l ength 40cm Composition: 100% linen Product reference: Aina V M ivory+w+lfr Care instructions: Machine wash (max 30oC) using a gentle cycle, hand wash (max 30oC) or dry-clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% handmade it may have some knots or natural unevenness. Note: Products can be customized, please contact us! STUDIO NATURAL HAND MADE IN LATVIA 100 % PRODUCED IN EUROPE', 'Elegant ivory sheer napkin, hand woven from premium linen and finished with a delicate handmade hemstitch. Decorative and practical element for a festive table. ---split--- Color: ivory Dimensions: w idth 40cm, l ength 40cm Composition: 100% linen Product reference: Aina V M ivory+w+lfr Care instructions: Machine wash (max 30oC) using a gentle cycle, hand wash (max 30oC) or dry-clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% handmade it may have some knots or natural unevenness. Note: Products can be customized, please contact us! STUDIO NATURAL HAND MADE IN LATVIA 100 % PRODUCED IN EUROPE', 'dev.Napkin', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'studio-natural-linen-napkin-anna-in-ivory-40x40cm';
