insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Linen napkin with shimmer and pearls 50x50 cm', 'These handwoven linen napkins are the perfect addition to special occasions and weddings. The handwoven fabric has a slight sheen and is decorated with hand sewn pearls on the sides, making it an eye-catching decor for you festive table. ---split--- Color: Natural with shimmer Dimensions: width 50cm, length 50cm Composition: 98% linen, 2% acetate Product reference: Ieva M krekl nat+w/silver+m1/ 4m perl Care instructions: Machine wash (max 30°C) using a gentle cycle, hand wash (max 30°C) or dry clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. Warning: Product color may slightly vary due to photographic lighting sources or your monitor settings. The silk string in the photo is not included in the price. Note: Products can be customized, please contact us! STUDIO NATURAL HANDMADE IN LATVIA', 'These handwoven linen napkins are the perfect addition to special occasions and weddings. The handwoven fabric has a slight sheen and is decorated with hand sewn pearls on the sides, making it an eye-catching decor for you festive table. ---split--- Color: Natural with shimmer Dimensions: width 50cm, length 50cm Composition: 98% linen, 2% acetate Product reference: Ieva M krekl nat+w/silver+m1/ 4m perl Care instructions: Machine wash (max 30°C) using a gentle cycle, hand wash (max 30°C) or dry clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. Warning: Product color may slightly vary due to photographic lighting sources or your monitor settings. The silk string in the photo is not included in the price. Note: Products can be customized, please contact us! STUDIO NATURAL HANDMADE IN LATVIA', 'dev.Napkin', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'studio-natural-linen-napkin-with-shimmer-and-pearls-50x50-cm';
