insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Linen tablecloth Azurs in white 140x210 cm', 'Dense hand woven white linen tablecloth with a see through square pattern. Perfect for midsummer evenings, important celebrations and even everyday use. ---split--- Color: W hite Dimensions: width 140cm, l ength 210cm Composition: 100% linen Product reference: Ažūrs M w+w+2LFR Care instructions: Machine wash (max 30 ° C) using a gentle cycle or dry clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. The napkins in the photo can be purchased in the napkins section. Note: Products can be customized, please contact us! STUDIO NATURAL HANDMADE IN LATVIA', 'Dense hand woven white linen tablecloth with a see through square pattern. Perfect for midsummer evenings, important celebrations and even everyday use. ---split--- Color: W hite Dimensions: width 140cm, l ength 210cm Composition: 100% linen Product reference: Ažūrs M w+w+2LFR Care instructions: Machine wash (max 30 ° C) using a gentle cycle or dry clean. Wash separately. Iron at maximum (high) temperature. Cockle is the very special effect of this fabric. As this fabric is 100% hand made it may have some knots or natural unevenness. The napkins in the photo can be purchased in the napkins section. Note: Products can be customized, please contact us! STUDIO NATURAL HANDMADE IN LATVIA', 'dev.Table cloth', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'studio-natural-linen-tablecloth-azurs-in-white-140x210-cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Leinentischdecke Azurs in Weiß 140x210 cm', 'Dichte, handgewebte Tischdecke aus weißem Leinen mit durchsichtigem Quadratmuster. Perfekt für Mittsommerabende, wichtige Feiern und sogar den täglichen Gebrauch. ---geteilt--- Farbe: Weiß Abmessungen: Breite 140 cm, Länge 210 cm Zusammensetzung: 100 % Leinen Produktreferenz: Ažūrs M w+w+2LFR Pflegehinweise: Maschinenwäsche (max. 30 °C) im Schonwaschgang oder chemische Reinigung. Getrennt waschen. Bei maximaler (hoher) Temperatur bügeln. Cockle ist der ganz besondere Effekt dieses Stoffes. Da dieser Stoff zu 100 % handgefertigt ist, kann es zu Knoten oder natürlichen Unebenheiten kommen. Die Servietten auf dem Foto können im Bereich Servietten erworben werden. Hinweis: Produkte können individuell angepasst werden, bitte kontaktieren Sie uns! STUDIO NATURAL HANDGEFERTIGT IN LETTLAND', 'Dichte, handgewebte Tischdecke aus weißem Leinen mit durchsichtigem Quadratmuster. Perfekt für Mittsommerabende, wichtige Feiern und sogar den täglichen Gebrauch. ---geteilt--- Farbe: Weiß Abmessungen: Breite 140 cm, Länge 210 cm Zusammensetzung: 100 % Leinen Produktreferenz: Ažūrs M w+w+2LFR Pflegehinweise: Maschinenwäsche (max. 30 °C) im Schonwaschgang oder chemische Reinigung. Getrennt waschen. Bei maximaler (hoher) Temperatur bügeln. Cockle ist der ganz besondere Effekt dieses Stoffes. Da dieser Stoff zu 100 % handgefertigt ist, kann es zu Knoten oder natürlichen Unebenheiten kommen. Die Servietten auf dem Foto können im Bereich Servietten erworben werden. Hinweis: Produkte können individuell angepasst werden, bitte kontaktieren Sie uns! STUDIO NATURAL HANDGEFERTIGT IN LETTLAND', 'dev.Table cloth', 'Natürliche Materialien', 'Handgefertigt' from public.products pr where pr.slug = 'studio-natural-linen-tablecloth-azurs-in-white-140x210-cm';
