insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Studio Natural gift card', 'Looking for the perfect gift but not sure what to choose? Our gift card is a simple and thoughtful way to let them pick what they truly love. Sent instantly by email, it can be redeemed anytime on our website or at our studio by appointment, and it remains timeless in style.', 'Looking for the perfect gift but not sure what to choose? Our gift card is a simple and thoughtful way to let them pick what they truly love. Sent instantly by email, it can be redeemed anytime on our website or at our studio by appointment, and it remains timeless in style.', 'Lifestyle object', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'studio-natural-studio-natural-gift-card';
