insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Big plate · Earth RAW', 'Whether you''re serving up a hearty dinner or a delicate array of treats, this terracotta plate will surely add warmth and beauty to your table. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'Whether you''re serving up a hearty dinner or a delicate array of treats, this terracotta plate will surely add warmth and beauty to your table. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'plate', 'earth raw, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-big-plate-earth-raw-1';
