insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 0.2L grey · Earth', 'A charming bowl for snacks, dips, or side salad with a grey-glazed interior. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'A charming bowl for snacks, dips, or side salad with a grey-glazed interior. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-small-grey-terracotta-bowl-12-5cm';
