insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 0.2L white · Earth', 'Nordic minimalist design meets carefully selected red clay and craftsmanship. Deeply rooted in our clay traditions, designed by our team of artisans. Simplicity and clean lines make this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Nordic minimalist design meets carefully selected red clay and craftsmanship. Deeply rooted in our clay traditions, designed by our team of artisans. Simplicity and clean lines make this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl, Earth', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-0-2l-white-earth';
