insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Bowl 0.2L · Earth RAW', 'Bring a touch of earthy elegance to your home. A charming bowl for snacks, dips, or side salads. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'Bring a touch of earthy elegance to your home. A charming bowl for snacks, dips, or side salads. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'bowl', 'Bowl', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-small-raw-terracotta-bowl-12-5cm';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 0.3L moss green · Earth', 'Thoughtfully handcrafted in Latvia, this small ceramic bowl is perfect for serving snacks, desserts, or a comforting bowl of rice. Finished with a smooth moss green glaze, it has slightly higher sides than our classic bowls. Simple, timeless, and versatile, it brings warmth and harmony to any table setting. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Thoughtfully handcrafted in Latvia, this small ceramic bowl is perfect for serving snacks, desserts, or a comforting bowl of rice. Finished with a smooth moss green glaze, it has slightly higher sides than our classic bowls. Simple, timeless, and versatile, it brings warmth and harmony to any table setting. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'plate', 'Bowl', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-0-3l-moss-green-earth';
