insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 0.6L · Earth RAW', 'The perfect bowl for any soups, salads, or breakfast foods. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'The perfect bowl for any soups, salads, or breakfast foods. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'bowl', 'Bowl, earth raw', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-0-6l-earth-raw';
