insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 1.0L · Earth RAW', 'A versatile 1.0 L bowl, thoughtfully sized for serving fresh salads or preparing ingredients in everyday cooking. This bowl celebrates the unrefined elegance of the earth. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'A versatile 1.0 L bowl, thoughtfully sized for serving fresh salads or preparing ingredients in everyday cooking. This bowl celebrates the unrefined elegance of the earth. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'bowl', 'Bowl, earth raw', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-1-0l-earth-raw';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Bowl 1.0L · Earth RAW', 'A versatile 1.0 L bowl, thoughtfully sized for serving fresh salads or preparing ingredients in everyday cooking. This bowl celebrates the unrefined elegance of the earth. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'A versatile 1.0 L bowl, thoughtfully sized for serving fresh salads or preparing ingredients in everyday cooking. This bowl celebrates the unrefined elegance of the earth. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'bowl', 'Bowl, earth raw', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-1-0l-earth-raw';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 2.0L curved moss green · Earth', 'Meet a bowl where every leafy green and plump tomato is celebrated in a feast for the senses. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Meet a bowl where every leafy green and plump tomato is celebrated in a feast for the senses. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-curved-moss-green-terracotta-salad-bowl-24cm';
