insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Bowl 2.0L · Earth RAW', 'Our raw terracotta salad bowl will infuse your dining table with a touch of natural elegance and charm. The bowl''s generous size makes it perfect for tossing and serving your favorite salads, fruits, or grains. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'Our raw terracotta salad bowl will infuse your dining table with a touch of natural elegance and charm. The bowl''s generous size makes it perfect for tossing and serving your favorite salads, fruits, or grains. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'bowl', 'Bowl, earth raw', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-bowl-2-0l-earth-raw';
