insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Breakfast bowl · Eclipse Gold', 'Bring a touch of sophistication to your breakfast table. The delicate gold rim adds a luxurious touch to your morning routine, making your cereal or oatmeal look and feel more special. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'Bring a touch of sophistication to your breakfast table. The delicate gold rim adds a luxurious touch to your morning routine, making your cereal or oatmeal look and feel more special. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-small-matte-black-breakfast-bowl-with-a-gold-rim';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Breakfast bowl · Eclipse Gold', 'Bring a touch of sophistication to your breakfast table. The delicate gold rim adds a luxurious touch to your morning routine, making your cereal or oatmeal look and feel more special. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'Bring a touch of sophistication to your breakfast table. The delicate gold rim adds a luxurious touch to your morning routine, making your cereal or oatmeal look and feel more special. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Laima Grigone', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-small-matte-black-breakfast-bowl-with-a-gold-rim';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Candle holder · Eclipse', 'Complement your evening rituals with the soft, subtle glow of candlelight, beautifully showcased on ceramic candle holder. Its simple, clean lines bring a natural, rustic charm to your home, and it is perfect for pillar candles.', 'Complement your evening rituals with the soft, subtle glow of candlelight, beautifully showcased on ceramic candle holder. Its simple, clean lines bring a natural, rustic charm to your home, and it is perfect for pillar candles.', 'plate', 'Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-candle-holder-eclipse';
