insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Chopstick holder', 'Give your chopsticks a place to rest. Crafted by hand from red and white clay, these holders bring the same quiet elegance to your table as the rest of the Vaidava Ceramics products. Small in size, but considered in every detail. The outside is left partially unglazed, revealing the natural texture and colour of the clay body, while the top is glazed in your choice of white, black, or transparent, so you can find the one that fits your favourite collection.', 'Give your chopsticks a place to rest. Crafted by hand from red and white clay, these holders bring the same quiet elegance to your table as the rest of the Vaidava Ceramics products. Small in size, but considered in every detail. The outside is left partially unglazed, revealing the natural texture and colour of the clay body, while the top is glazed in your choice of white, black, or transparent, so you can find the one that fits your favourite collection.', 'plate', 'Earth', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-candle-holder-eclipse-copy';
