insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dessert bowl · Eclipse', 'Its smooth, velvety texture invites you to explore its indulgent delights. The small bowl may be unassuming, but it holds within it the power to elevate any dessert into a work of art. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'Its smooth, velvety texture invites you to explore its indulgent delights. The small bowl may be unassuming, but it holds within it the power to elevate any dessert into a work of art. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Eclipse, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-dessert-bowl-eclipse';
