insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dessert bowl · Eclipse Gold', 'Adding a touch of elegance to your table. This bowl is perfect for serving individual portions of your favorite desserts, such as ice cream, pudding, or fruit salads. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'Adding a touch of elegance to your table. This bowl is perfect for serving individual portions of your favorite desserts, such as ice cream, pudding, or fruit salads. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Eclipse Gold, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-dessert-bowl-eclipse-gold';
