insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dessert plate x 2 · Eclipse', 'Make each dessert an unforgettable experience that lingers long after the last crumb is savored. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'Make each dessert an unforgettable experience that lingers long after the last crumb is savored. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'plate', 'Eclipse, Laima Grigone, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-dessert-plate-x-2-eclipse';
