insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Dinner plate · Eclipse Gold', 'Gracefully designed with gatherings in mind, these dinner plates bring a refined presence to the table - ideal for special occasions, yet equally suited for elevating everyday meals. Their elegant form and thoughtful craftsmanship turn even the simplest dish into something memorable. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'Gracefully designed with gatherings in mind, these dinner plates bring a refined presence to the table - ideal for special occasions, yet equally suited for elevating everyday meals. Their elegant form and thoughtful craftsmanship turn even the simplest dish into something memorable. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'plate', 'Laima Grigone, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-dinner-plate-eclipse-gold';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Dinner plate · Eclipse Gold', 'Gracefully designed with gatherings in mind, these dinner plates bring a refined presence to the table - ideal for special occasions, yet equally suited for elevating everyday meals. Their elegant form and thoughtful craftsmanship turn even the simplest dish into something memorable. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'Gracefully designed with gatherings in mind, these dinner plates bring a refined presence to the table - ideal for special occasions, yet equally suited for elevating everyday meals. Their elegant form and thoughtful craftsmanship turn even the simplest dish into something memorable. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'plate', 'Laima Grigone, Plate', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-dinner-plate-eclipse-gold';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Espresso cup set · Eclipse', 'This set is a perfect addition to a cozy breakfast nook, an intimate gathering with friends, or simply to enjoy a solo espresso moment. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'This set is a perfect addition to a cozy breakfast nook, an intimate gathering with friends, or simply to enjoy a solo espresso moment. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'cup', 'Cup, Eclipse, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-espresso-cup-set-eclipse';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Espresso cup set · Eclipse', 'This set is a perfect addition to a cozy breakfast nook, an intimate gathering with friends, or simply to enjoy a solo espresso moment. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'This set is a perfect addition to a cozy breakfast nook, an intimate gathering with friends, or simply to enjoy a solo espresso moment. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'cup', 'Cup, Eclipse, Laima Grigone', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-espresso-cup-set-eclipse';
