insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Gift set "SCENT"', 'SILMACHY soap and VAIDAVA CERAMICS mug and soap dish Gift the feeling of warmth, comfort, and simple beauty with this set that brings together natural skincare and handcrafted ceramic design. Set includes: SILMACHY orange and cinnamon soap Handmade creation made only with natural ingredients that gently care for the skin and offer a delightful, warm aroma. This soap bar is like a small touch of festive spirit in your everyday routine. VAIDAVA CERAMICS collection Eclipse mug Elegant design that blends timeless craftsmanship with modern minimalism. VAIDAVA CERAMICS collection Eclipse soap dish Hand crafted ceramic dish that combines elegance with practicality. Its minimalist design fits beautifully into any bathroom or kitchen interior. The “Scent” set combines the festive aroma of orange and cinnamon with the timeless elegance of VAIDAVA CERAMICS craftsmanship. The handmade Silmachy soap gently nourishes the skin, while the minimalist Eclipse mug and matching soap dish add harmony and sophistication to your daily routine.', 'SILMACHY soap and VAIDAVA CERAMICS mug and soap dish Gift the feeling of warmth, comfort, and simple beauty with this set that brings together natural skincare and handcrafted ceramic design. Set includes: SILMACHY orange and cinnamon soap Handmade creation made only with natural ingredients that gently care for the skin and offer a delightful, warm aroma. This soap bar is like a small touch of festive spirit in your everyday routine. VAIDAVA CERAMICS collection Eclipse mug Elegant design that blends timeless craftsmanship with modern minimalism. VAIDAVA CERAMICS collection Eclipse soap dish Hand crafted ceramic dish that combines elegance with practicality. Its minimalist design fits beautifully into any bathroom or kitchen interior. The “Scent” set combines the festive aroma of orange and cinnamon with the timeless elegance of VAIDAVA CERAMICS craftsmanship. The handmade Silmachy soap gently nourishes the skin, while the minimalist Eclipse mug and matching soap dish add harmony and sophistication to your daily routine.', 'Lifestyle object', 'Natural materials', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-gift-set-touch';
