insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Large bowl · Eclipse', 'Its spacious size is perfect for an abundant salad or a colorful assortment of fruit. The bowl''s minimalist design fades into the background, allowing the vibrant colors and textures of its contents to take center stage. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'Its spacious size is perfect for an abundant salad or a colorful assortment of fruit. The bowl''s minimalist design fades into the background, allowing the vibrant colors and textures of its contents to take center stage. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Eclipse, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-large-bowl-eclipse';
