insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Large bowl · Eclipse Gold', 'Rooted in the rhythm of the earth and shaped by human hands, this bowl is more than a vessel - it is a story told in clay. A poetic blend of function and form, it’s ideal for serving fresh salads or presenting fruit with elegance. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each bowl carries the soul of the material and the care of its makers.', 'Rooted in the rhythm of the earth and shaped by human hands, this bowl is more than a vessel - it is a story told in clay. A poetic blend of function and form, it’s ideal for serving fresh salads or presenting fruit with elegance. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each bowl carries the soul of the material and the care of its makers.', 'bowl', 'Bowl, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-large-bowl-eclipse-gold';
