insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Lunch Bowl Set (6 pcs) · Eclipse Gold', 'Where deep matte tones meet a fine gold rim, these lunch bowls embody refined simplicity and quiet sophistication. Crafted using the ancient Terra Sigillata technique, they balance artisanal heritage with a modern Nordic aesthetic. Ideal for everyday meals, salads, grain bowls or thoughtfully plated dishes, this six-piece set elevates lunchtime into a calm, elegant ritual.', 'Where deep matte tones meet a fine gold rim, these lunch bowls embody refined simplicity and quiet sophistication. Crafted using the ancient Terra Sigillata technique, they balance artisanal heritage with a modern Nordic aesthetic. Ideal for everyday meals, salads, grain bowls or thoughtfully plated dishes, this six-piece set elevates lunchtime into a calm, elegant ritual.', 'plate', 'Bowl, Eclipse Gold, Laima Grigone, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-lunch-bowl-set-6-pcs-eclipse-gold';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Lunch Bowl Set (6 pcs) · Eclipse Gold', 'Where deep matte tones meet a fine gold rim, these lunch bowls embody refined simplicity and quiet sophistication. Crafted using the ancient Terra Sigillata technique, they balance artisanal heritage with a modern Nordic aesthetic. Ideal for everyday meals, salads, grain bowls or thoughtfully plated dishes, this six-piece set elevates lunchtime into a calm, elegant ritual.', 'Where deep matte tones meet a fine gold rim, these lunch bowls embody refined simplicity and quiet sophistication. Crafted using the ancient Terra Sigillata technique, they balance artisanal heritage with a modern Nordic aesthetic. Ideal for everyday meals, salads, grain bowls or thoughtfully plated dishes, this six-piece set elevates lunchtime into a calm, elegant ritual.', 'plate', 'Bowl, Eclipse Gold, Laima Grigone, Set', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-lunch-bowl-set-6-pcs-eclipse-gold';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Lunch bowl · Eclipse', 'This bowl is perfect for a nourishing mid-day meal, with ample space for soup or salad. Its minimalist design serves as a blank canvas, allowing your lunch''s colorful ingredients to shine. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'This bowl is perfect for a nourishing mid-day meal, with ample space for soup or salad. Its minimalist design serves as a blank canvas, allowing your lunch''s colorful ingredients to shine. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from pure red clay. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Eclipse, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-lunch-bowl-eclipse';
