insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Lunch bowl · Eclipse Gold', 'This versatile bowl with a delicate gold rim is perfect for hearty portions of your favorite meals, including salads, soups, and noodle dishes. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'This versatile bowl with a delicate gold rim is perfect for hearty portions of your favorite meals, including salads, soups, and noodle dishes. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'bowl', '3-5 dienas, Bowl, Eclipse Gold, Laima Grigone', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-lunch-bowl-eclipse-gold';
