insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Medium plate · Earth', 'The most versatile plate for your tableware setting, great for daily meals as well as special occasions. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'The most versatile plate for your tableware setting, great for daily meals as well as special occasions. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'plate', 'Earth, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-medium-plate-earth';
