insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Medium plate · Earth RAW', 'The most versatile plate for your tableware setting, great for daily meals as well as special occasions. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'The most versatile plate for your tableware setting, great for daily meals as well as special occasions. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'plate', 'earth raw, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-medium-plate-earth-raw-1';
