insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Mug glazed moss green · Earth', 'Add a touch of comfort to your morning routine. Enjoy your solitary coffee moments or tea times with friends using our exquisite terracotta mug. A splendid and practical enhancement for any kitchen space. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is partially glazed with moss green coloured glaze. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Add a touch of comfort to your morning routine. Enjoy your solitary coffee moments or tea times with friends using our exquisite terracotta mug. A splendid and practical enhancement for any kitchen space. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is partially glazed with moss green coloured glaze. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'mug', 'End of Era, Mug', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-mug-glazed-moss-green-earth';
