insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Mug · Earth RAW', 'Give your morning the cosiness it needs. Whether you''re enjoying a solo cup of coffee or sharing a pot of tea with friends, our terracotta mug is a beautiful and functional addition to any kitchen. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'Give your morning the cosiness it needs. Whether you''re enjoying a solo cup of coffee or sharing a pot of tea with friends, our terracotta mug is a beautiful and functional addition to any kitchen. Designed by our team of artisans. The Earth RAW collection pays tribute to the purest and most rustic expression of our clay, all while embodying the sophistication and sleekness of Nordic design. Each piece is a celebration of the beauty and authenticity of the natural world. The outside is left naturally raw, leveled, and slightly glazed. This product is glazed with lead-less glaze and tempered at 1000 C.', 'mug', 'earth raw, Mug', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-mug-earth-raw-1';
