insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Mug · Eclipse', 'Savor your beverages in ultimate style with this truly versatile mug, that effortlessly adds sophistication and elegance to any intimate dinner setting, while also being your go-to favorite during a busy work week. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'Savor your beverages in ultimate style with this truly versatile mug, that effortlessly adds sophistication and elegance to any intimate dinner setting, while also being your go-to favorite during a busy work week. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'mug', 'Eclipse, Laima Grigone, Mug', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-mug-eclipse';
