insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Mug · Eclipse Gold', 'A sophisticated addition to your drinkware collection. The generous size of the mug makes it perfect for sipping on your favorite hot beverage, whether it''s a comforting cup of tea or a rich cup of coffee. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'A sophisticated addition to your drinkware collection. The generous size of the mug makes it perfect for sipping on your favorite hot beverage, whether it''s a comforting cup of tea or a rich cup of coffee. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'mug', '10-14 dienas, Eclipse Gold, Laima Grigone, Mug', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-mug-eclipse-gold';
