insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.1 - Lunch Set · Earth', 'Bowl 0.6L white · Earth Size: 16.5 cm × 6 cm · 0.6 L · 0.4 kg Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg Whether it''s a casual meal or a celebratory feast, this set of dishes is suitable for three courses of your choice. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Bowl 0.6L white · Earth Size: 16.5 cm × 6 cm · 0.6 L · 0.4 kg Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg Whether it''s a casual meal or a celebratory feast, this set of dishes is suitable for three courses of your choice. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl, Earth, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-nr-1-lunch-set-earth';
