insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.10- Espresso Set with a Plate · Eclipse', 'Dinner plate · Eclipse Size: 29 cm × 2.5 cm · 1.2 kg Espresso cup set · Eclipse Size: 7.4 cm × 5.5 cm · 100 mL · 0.2 kg Like a canvas, this plate is waiting for its next masterpiece. Complemented with dipping bowls, it will have extra use when serving snacks for different tastes. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'Dinner plate · Eclipse Size: 29 cm × 2.5 cm · 1.2 kg Espresso cup set · Eclipse Size: 7.4 cm × 5.5 cm · 100 mL · 0.2 kg Like a canvas, this plate is waiting for its next masterpiece. Complemented with dipping bowls, it will have extra use when serving snacks for different tastes. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'plate', 'Cup, Eclipse, Laima Grigone, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-10-espresso-set-with-a-plate-eclipse';
