insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.11 - Plate Set · Earth', '2 x Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg A set of plates that will complement both everyday meals and celebratory feasts. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', '2 x Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg A set of plates that will complement both everyday meals and celebratory feasts. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'plate', 'Earth, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-11-plate-set-earth';
