insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.12 - Plate Set · Earth', '4 x Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg A set of medium-sized plates that will make a practical addition to any kitchen. Ideal for serving salads and appetizers at family dinners or casual meals. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', '4 x Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg A set of medium-sized plates that will make a practical addition to any kitchen. Ideal for serving salads and appetizers at family dinners or casual meals. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'plate', 'Earth, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-12-plate-set-earth';
