insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.14 - Mug Set · Earth', '2 x Mug · Earth Size: 7.5 cm × 10.5 cm · 0.3 kg · 0.3 l The mugs are perfect for enjoying morning coffee, afternoon tea, or a refreshing cold drink with a special someone. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', '2 x Mug · Earth Size: 7.5 cm × 10.5 cm · 0.3 kg · 0.3 l The mugs are perfect for enjoying morning coffee, afternoon tea, or a refreshing cold drink with a special someone. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'mug', 'Earth, Mug, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-14-mug-set-earth';
