insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.19 - Large Lunch Set · Earth', '4 x Bowl 0.6L white · Earth Size: 16.5 cm × 6 cm · 0.6 L · 0.4 kg 4 x Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg 4 x Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg Whether it''s an everyday meal or a celebratory feast, this dinnerware set will perfectly accommodate three courses of your choice. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', '4 x Bowl 0.6L white · Earth Size: 16.5 cm × 6 cm · 0.6 L · 0.4 kg 4 x Medium plate · Earth Size: 22 cm × 2.5 cm · 0.65 kg 4 x Big plate · Earth Size: 26.5 cm × 2 cm · 0.75 kg Whether it''s an everyday meal or a celebratory feast, this dinnerware set will perfectly accommodate three courses of your choice. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl, Earth, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-19-large-lunch-set-earth';
