insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.20 - Dinner Plate Set · Earth Raw', '4 x Big plate · Earth Raw Size: 26.5 cm × 2 cm · 0.75 kg Elevate your dining experience with the Earth Raw dinner plate set — a tribute to natural elegance and Nordic minimalism. Each plate is handcrafted from terracotta clay, with the exterior left raw and tactile, while the surface is finished with a lead-free glaze and tempered at 1000 °C. This combination highlights the authentic character of clay and ensures durability for daily use. Generously sized, these plates are perfect for serving main courses, festive dinners, or creating a refined table setting that celebrates timeless craftsmanship. Features: Handcrafted terracotta dinner plates Beige, lead-free glaze on the inside, tempered at 1000 °C Natural clay with a subtle touch of glaze on the exterior Ideal for main dishes and elegant table presentations', '4 x Big plate · Earth Raw Size: 26.5 cm × 2 cm · 0.75 kg Elevate your dining experience with the Earth Raw dinner plate set — a tribute to natural elegance and Nordic minimalism. Each plate is handcrafted from terracotta clay, with the exterior left raw and tactile, while the surface is finished with a lead-free glaze and tempered at 1000 °C. This combination highlights the authentic character of clay and ensures durability for daily use. Generously sized, these plates are perfect for serving main courses, festive dinners, or creating a refined table setting that celebrates timeless craftsmanship. Features: Handcrafted terracotta dinner plates Beige, lead-free glaze on the inside, tempered at 1000 °C Natural clay with a subtle touch of glaze on the exterior Ideal for main dishes and elegant table presentations', 'plate', 'earth raw, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-20-big-plate-set-earth-copy';
