insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'No.8- Lunch Set · Eclipse', 'Breakfast bowl · Eclipse Size: 14.8 cm × 8 cm · 0.75 L · 0.55 kg Lunch bowl · Eclipse Size: 25 cm × 6 cm · 1.1 L · 0.95 kg Dinner plate · Eclipse Size: 29 cm × 2.5 cm · 1.2 kg Each meal is like a little work of art, not only for the taste buds, but also for visual enjoyment. The three-course meal set will create a festive feeling even in everyday life. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'Breakfast bowl · Eclipse Size: 14.8 cm × 8 cm · 0.75 L · 0.55 kg Lunch bowl · Eclipse Size: 25 cm × 6 cm · 1.1 L · 0.95 kg Dinner plate · Eclipse Size: 29 cm × 2.5 cm · 1.2 kg Each meal is like a little work of art, not only for the taste buds, but also for visual enjoyment. The three-course meal set will create a festive feeling even in everyday life. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'bowl', 'Bowl, Eclipse, Laima Grigone, Plate, Set', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-no-8-lunch-set-eclipse';
