insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Serving plate · Eclipse', 'Serve up delicious culinary creations, on a serving plate that is a true statement piece, adding a touch of elegance and refinement to any table setting or special occasion. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'Serve up delicious culinary creations, on a serving plate that is a true statement piece, adding a touch of elegance and refinement to any table setting or special occasion. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Handmade using traditional methods and materials, our tableware is crafted from natural red clay. Each piece is glazed and tempered at 1000°C.', 'plate', 'Eclipse, Laima Grigone, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-serving-plate-eclipse';
