insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Serving plate · Eclipse Gold', 'This serving plate is designed to do more than hold food - it sets the tone for the table. Perfect for presenting shared dishes like charcuterie, roasted vegetables, or seasonal salads, it becomes part of the ritual of gathering. A piece that serves with intention, inviting both nourishment and connection. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'This serving plate is designed to do more than hold food - it sets the tone for the table. Perfect for presenting shared dishes like charcuterie, roasted vegetables, or seasonal salads, it becomes part of the ritual of gathering. A piece that serves with intention, inviting both nourishment and connection. Crafted from red clay and fired at 1000°C, the exterior is finished in a soft matte black using the ancient Terra Sigillata technique. The interior reveals a deep black glaze, while a delicate gold rim adds a subtle touch of warmth and refinement. Designed by Laima Grigone and brought to life within our workshop, each plate carries the soul of the material and the care of its makers.', 'plate', 'Laima Grigone, Plate', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-serving-plate-eclipse-gold';
