insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Snack bowl set with tray grey · Earth', 'Add a touch of rustic charm to your dining table with our set of 3 mini terracotta bowls. Perfect for serving dips, sauces, or small appetizers. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'Add a touch of rustic charm to your dining table with our set of 3 mini terracotta bowls. Perfect for serving dips, sauces, or small appetizers. Designed by our team of artisans. Simplicity and clean lines make any piece in this collection a masterpiece of timeless design. The outside is left unglazed. It''s leveled and thoroughly polished to disclose the clay''s smoothness and prevent water and dirt absorption.', 'bowl', 'Bowl', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-set-of-3-mini-grey-terracotta-bowls';
