insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Vase · Eclipse', 'A stunning piece of home decor that seamlessly blends modern minimalism with classic elegance – a beautiful vase for showcasing your flowers. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'A stunning piece of home decor that seamlessly blends modern minimalism with classic elegance – a beautiful vase for showcasing your flowers. Designed by Laima Grigone. This collection harmoniously fuses the ancient technique of Terra Sigillata and clean, balanced, minimalist design with Nordic nature''s rugged yet delicate beauty for a timeless and contemporary aesthetic. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'vase', 'Eclipse, Laima Grigone, Vase', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-vase-eclipse';
