insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'en', 'Vase · Eclipse Gold', 'The vase is perfect for showcasing your favorite flowers, whether it''s a single stem or a lush bouquet. The delicate gold rim adds a touch of luxury to your floral arrangements, creating an elegant look that is sure to impress. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'The vase is perfect for showcasing your favorite flowers, whether it''s a single stem or a lush bouquet. The delicate gold rim adds a touch of luxury to your floral arrangements, creating an elegant look that is sure to impress. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'vase', 'Laima Grigone, Vase', 'Handcrafted' from public.products pr where pr.slug = 'vaidava-ceramics-matte-black-flower-vase-with-a-gold-rim';
insert into public.product_translations (product_id, locale, name, description, story, craft, materials, technique) select pr.id, 'de', 'Vase · Eclipse Gold', 'The vase is perfect for showcasing your favorite flowers, whether it''s a single stem or a lush bouquet. The delicate gold rim adds a touch of luxury to your floral arrangements, creating an elegant look that is sure to impress. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'The vase is perfect for showcasing your favorite flowers, whether it''s a single stem or a lush bouquet. The delicate gold rim adds a touch of luxury to your floral arrangements, creating an elegant look that is sure to impress. Designed by Laima Grigone. The dark colors of this collection, delicately decorated with a gold rim, bring elegance to the otherwise mundane. Our tableware is crafted from natural red clay and is handmade using traditional methods and materials. Each piece is glazed and tempered at 1000°C.', 'vase', 'Laima Grigone, Vase', 'Handgefertigt' from public.products pr where pr.slug = 'vaidava-ceramics-matte-black-flower-vase-with-a-gold-rim';
